  const inputEl      = $("input");
  const sendBtn      = $("send");
  const stopBtn      = $("chip-stop");
  const chipContext  = $("chip-context");
  const chipModel    = $("chip-model");
  const chipEffort   = $("chip-effort");
  const chipView     = $("chip-view");
  const chipGen      = $("chip-gen");
  const chipSlash    = $("chip-slash");
  const chipReact    = $("chip-react");
  const chipSession  = $("chip-session");
