  const threadsBtn   = $("threads-btn");
  const drawer       = $("drawer");
  const drawerOverlay= $("drawer-overlay");
  const drawerClose  = $("drawer-close");
  const threadList   = $("thread-list");
  const threadNewBtn = $("thread-new");
  const threadToggleBtn = $("thread-toggle");
  const drawerHeaderEl  = document.querySelector("#drawer .drawer-header");
  const threadSearchInput  = $("thread-search-input");
  const threadSearchClear  = $("thread-search-clear");
  const threadSearchAI     = $("thread-search-ai");
  const threadSearchStatus = $("thread-search-status");
  const searchHistoryEl    = $("search-history");
  const techSearchHistoryEl = $("tech-search-history");
  const drawerViews   = $("drawer-views");
  const drawerHomeEl  = $("drawer-home");
  const drawerTitleEl = $("drawer-title");
