  const routinesRefresh = $("routines-refresh");
  const routinesAdd = $("routines-add");
  const routinesList = $("routines-list");
  const routinesEmpty = $("routines-empty");
  const healthPage = $("health-page");
  const healthBack = $("health-back");
  const healthRefresh = $("health-refresh");
  const healthListEl = $("health-list");
  const healthEmpty = $("health-empty");
  const healthBadge = $("health-badge");
