  const connectionRefresh = $("connection-refresh");
  const newsPage = $("news-page");
  const newsBack = $("news-back");
  const newsRefresh = $("news-refresh");
  const newsBadge = $("news-badge");
  const newsListEl = $("news-list");
  const newsEmpty = $("news-empty");
