  function escHtml(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  const URL_RE = /\bhttps?:\/\/[^\s<>()"'`]+[^\s<>()"'`.,;:!?]/g;
  const PATH_RE = /^(~\/|\/)[^\s`<>"']+?(?::\d+(?::\d+)?)?$/;
  const REL_PATH_RE = /^[A-Za-z0-9_.-]+(\/[A-Za-z0-9_.-]+)+(?::\d+(?::\d+)?)?$/;
  const LINE_SUFFIX_RE = /:\d+(?::\d+)?$/;
  const KNOWN_BASENAME_ALIASES = {
    "CLAUDE.md": "/Users/Kirill/.claude/CLAUDE.md",
    "MEMORY.md": "/Users/Kirill/.claude/projects/-Users-Kirill-Documents------2---------/memory/MEMORY.md",
    "settings.json": "/Users/Kirill/.claude/settings.json",
    "settings.local.json": "/Users/Kirill/.claude/settings.local.json",
    "scheduled-tasks.json": "/Users/Kirill/.claude/scheduled-tasks.json",
    "keybindings.json": "/Users/Kirill/.claude/keybindings.json",
  };

  function stripLineSuffix(s) {
    return String(s || "").trim().replace(LINE_SUFFIX_RE, "");
  }

  function resolvePathHint(s) {
    const t = String(s || "").trim();
    if (!t) return null;
    if (PATH_RE.test(t)) {
      const base = stripLineSuffix(t);
      if (!base || base.endsWith("/")) return null;
      if (/\/[^/]*\.[A-Za-z0-9]{1,8}$/.test(base)) return t;
      if (base.startsWith("~/.claude") || base.startsWith("/Users/Kirill/.claude")) return t;
      return null;
    }
    if (Object.prototype.hasOwnProperty.call(KNOWN_BASENAME_ALIASES, t)) {
      return KNOWN_BASENAME_ALIASES[t];
    }
    if (REL_PATH_RE.test(t)) {
      const base = stripLineSuffix(t);
      if (/\/[^/]*\.[A-Za-z0-9]{1,8}$/.test(base)) return t;
      if (/(?:^|\/)SKILL\.md$/.test(base)) return t;
    }
    return null;
  }

  function isFilePathLike(s) {
    return resolvePathHint(s) != null;
  }

