  function ensureBotActions(el) {
    if (!el || !el.classList || !el.classList.contains("bot") || el.classList.contains("tool")) return;
    if (el.querySelector(":scope > .msg-actions")) return;
    const body = el.querySelector(".body");
    if (!body || !body.textContent.trim()) return; // пусто/ещё печатается — позже
    const bar = document.createElement("div");
    bar.className = "msg-actions";
    const bTts = document.createElement("button");
    bTts.type = "button";
    bTts.className = "msg-act-btn";
    bTts.title = "Озвучить";
    bTts.setAttribute("aria-label", "Озвучить");
    bTts.innerHTML = _MSG_TTS_SVG;
    bTts.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); toggleMsgTts(el, bTts); });
    const bCopy = document.createElement("button");
    bCopy.type = "button";
    bCopy.className = "msg-act-btn";
    bCopy.title = "Скопировать";
    bCopy.setAttribute("aria-label", "Скопировать");
    bCopy.innerHTML = _MSG_COPY_SVG;
    bCopy.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); copyMsgText(el, bCopy); });
    bar.appendChild(bTts);
    bar.appendChild(bCopy);
    el.appendChild(bar);
  }
  function scanBotActions() {
    if (!chatEl) return;
    try { chatEl.querySelectorAll(".msg.bot").forEach(ensureBotActions); } catch (_) {}
  }

