      togRow.appendChild(tog);
      togRow.appendChild(togLbl);
      body.appendChild(togRow);

      // cron-блок: всё (инпут, помощь, расшифровка, пресеты) внутри сворачиваемого «быстрый выбор времени»
      const cronWrap = document.createElement("div");
      cronWrap.className = "routine-cron";

