      const cronInner = document.createElement("div");
      cronInner.className = "routine-cron-inner";
      cronInner.hidden = true;

      const cronInputRow = document.createElement("div");
      cronInputRow.className = "routine-cron-input-row";
      const cronInput = document.createElement("input");
      cronInput.type = "text";
      cronInput.className = "routine-cron-input";
      cronInput.value = it.cron || "";
      cronInput.placeholder = "0 10 * * 1-5";
      const savedCron = it.cron || "";
      const cronHelpBtn = document.createElement("button");
      cronHelpBtn.type = "button";
      cronHelpBtn.className = "routine-cron-help-btn";
      cronHelpBtn.textContent = "?";
