  function pushCommandTrace(cmd, arg) {
    if (!cmd) return;
    let text = "▸ /" + cmd.name;
    if (arg) text += " " + arg;
    if (cmd.desc) text += " — " + cmd.desc;
    try { pushMsg("system", text, "", Date.now()); } catch (_) {}
  }

  function showSlashHelp() {
    const groups = [
      { title: "Управление", items: SLASH_COMMANDS.filter((c) => c.group === "control") },
      { title: "Воркфлоу KINEMOTOR", items: SLASH_COMMANDS.filter((c) => c.group === "workflow") },
      { title: "Инструменты", items: SLASH_COMMANDS.filter((c) => c.group === "tools") },
      { title: "Сервис", items: SLASH_COMMANDS.filter((c) => c.group === "meta") },
    ];
    let html = "";
    for (const g of groups) {
      if (!g.items.length) continue;
      html += `<div class="slash-help-group"><div class="slash-help-title">${g.title}</div>`;
      for (const c of g.items) {
        const arg = c.needsArg ? ` <i>&lt;текст&gt;</i>` : "";
        const det = c.details || c.desc;
        html += `<div class="slash-help-item" data-cmd="${c.name}"><div class="slash-help-name">/${c.name}${arg}</div><div class="slash-help-desc">${det}</div></div>`;
      }
      html += `</div>`;
    }
    modalTitle.textContent = "слэш-команды";
    modalBody.innerHTML = html;
    modal.classList.remove("hidden");
    modalBody.querySelectorAll(".slash-help-item[data-cmd]").forEach((item) => {
      item.addEventListener("click", () => {
        const name = item.getAttribute("data-cmd");
        const cmd = SLASH_COMMANDS.find((x) => x.name === name);
        if (!cmd) return;
        haptic.tap();
        if (cmd.needsArg) {
          modal.classList.add("hidden");
          inputEl.value = `/${cmd.name} `;
          if (inputEl.parentElement) inputEl.parentElement.classList.add("has-content");
          autoResize();
          inputEl.focus();
        } else {
          modal.classList.add("hidden");
          pushCommandTrace(cmd);
          try { cmd.run(); } catch (e) { console.error("slash cmd failed", e); toast("команда упала"); }
        }
      });
    });
  }

