  function findSlashCommand(text) {
    const m = text.match(/^\/([a-zA-Z][\w-]*)(?:\s+([\s\S]*))?$/);
    if (!m) return null;
    const name = m[1].toLowerCase();
    const arg = (m[2] || "").trim();
    const cmd = SLASH_COMMANDS.find((c) => c.name === name);
    return { name, arg, cmd };
  }

  function maybeRunSlashCommand() {
    const raw = inputEl.value;
    if (!raw) return false;
    const trimmed = raw.trim();
    if (!trimmed.startsWith("/")) return false;
    // escape: //foo -> literal /foo
    if (trimmed.startsWith("//")) {
      const idx = raw.indexOf("/");
      inputEl.value = raw.slice(0, idx) + raw.slice(idx + 1);
      return false;
    }
    const parsed = findSlashCommand(trimmed);
    if (!parsed) return false;
    const { name, arg, cmd } = parsed;
    if (!cmd) {
      toast(`неизвестная команда: /${name}`, 2200);
      haptic.warn();
      inputEl.value = "";
      if (inputEl.parentElement) inputEl.parentElement.classList.remove("has-content");
      autoResize(true);
      hideSlashSuggest();
      return true;
    }
    if (cmd.needsArg && !arg) {
      toast(`/${name} требует аргумент`, 2200);
      haptic.warn();
      return true;
    }
    inputEl.value = "";
    if (inputEl.parentElement) inputEl.parentElement.classList.remove("has-content");
    autoResize(true);
    hideSlashSuggest();
    {
      const _tid = state.currentThread;
      if (_tid && _tid !== "favorites") {
        setDraftLocal(_tid, "");
        flushDraftToServer(_tid, "");
      }
    }
    pushCommandTrace(cmd, arg);
    try { cmd.run(arg); } catch (e) { console.error("slash cmd failed", e); toast("команда упала"); }
    return true;
  }

  // dropdown
  let slashSuggestEl = null;
  let slashSuggestList = [];
  let slashSuggestIdx = 0;

  let chipPopoverEl = null;
  let genPopoverView = null;   // null = настройки Ген, "model" = раскрытый список моделей
  let genScrollTop = 0;        // память прокрутки списка опций между перерисовками (чтобы не прыгал наверх при тапе)
  function hideChipPopover(immediate) {
    if (!chipPopoverEl) chipPopoverEl = document.getElementById("chip-popover");
    if (!chipPopoverEl) return;
    if (chipPopoverEl.classList.contains("hidden")) return;
    genPopoverView = null;
    genScrollTop = 0;
    if (immediate) {
      chipPopoverEl.classList.remove("closing");
      chipPopoverEl.classList.add("hidden");
      chipPopoverEl.innerHTML = "";
      return;
    }
    chipPopoverEl.classList.add("closing");
    const onEnd = () => {
      chipPopoverEl.removeEventListener("animationend", onEnd);
      if (!chipPopoverEl.classList.contains("closing")) return;
      chipPopoverEl.classList.remove("closing");
      chipPopoverEl.classList.add("hidden");
      chipPopoverEl.innerHTML = "";
    };
    chipPopoverEl.addEventListener("animationend", onEnd, { once: true });
  }

  function renderChipPopover(items, currentKey) {
    if (!chipPopoverEl) chipPopoverEl = document.getElementById("chip-popover");
    if (!chipPopoverEl) return;
    if (!items || !items.length) { hideChipPopover(true); return; }
    let html = "";
    items.forEach((it, i) => {
      const cls = (currentKey != null && it.key === currentKey)
        ? "slash-suggest-row active"
        : "slash-suggest-row";
      const desc = it.desc ? `<div class="slash-suggest-desc">${it.desc}</div>` : "";
      html += `<div class="${cls}" data-idx="${i}"><div class="slash-suggest-name">${it.label}</div>${desc}</div>`;
    });
    chipPopoverEl.innerHTML = html;
    chipPopoverEl.classList.remove("hidden", "closing");
    chipPopoverEl.querySelectorAll(".slash-suggest-row").forEach((row) => {
      let fired = false;
      const trigger = () => {
        if (fired) return;
        fired = true;
        const i = parseInt(row.getAttribute("data-idx") || "0", 10);
        const it = items[i];
        if (!it) return;
        haptic.tap();
        try { it.run && it.run(); } catch (e) { console.error("chip popover action failed", e); }
        hideChipPopover();
      };
      row.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
      row.addEventListener("pointerup",   (e) => { e.stopPropagation(); trigger(); });
      row.addEventListener("click",       (e) => { e.stopPropagation(); trigger(); });
    });
  }

  // ── chip «Ген»: настройки генерации медиа (источник/модель/кол-во) ──────────
  // Тред-скоуп, уходят Маккоду скрыто через --append-system-prompt (см. сервер),
  // в чате не отображаются. Поповер — toggle-строки: тап циклит значение и
  // НЕ закрывается (можно настроить всё за один заход), «Сбросить» — закрывает.
  const GEN_TYPES = ["image", "video"];
  const GEN_TYPE_LABELS = { image: "Картинка", video: "Видео" };
  const GEN_SOURCE_LABELS = { auto: "Авто", pollinations: "Pollinations", magnific: "Magnific" };
  // Лейблы и «лирика» моделей. Ключ модели — это РОВНО то, что уйдёт в `--model X`
  // скилла magnific-gen (см. miniapp_ws.py), а generate.py матчит его подстрокой по
  // названию кнопки в живом UI Magnific. Поэтому ключи — короткие токены без точек
  // (точка в «Flux.2» ломает подстрочный матч). Список снят с реального каталога
  // Magnific (44 image- + ~30 video-моделей) — берём ходовое подмножество.
  const GEN_MODEL_LABELS = {
    auto: "Авто", flux: "FLUX", turbo: "Turbo",
    // video
    veo: "Veo 3.1", kling: "Kling 3.0", hailuo: "Hailuo", wan: "Wan 2.7",
    seedance: "Seedance 2.0", runway: "Runway", grok: "Grok", ltx: "LTX 2",
    // image
    nanobanana2: "Nano Banana 2", gpt2: "GPT-2 Image", seedream: "Seedream 5",
    mystic: "Mystic 2.5", cinematic: "Cinematic", ideogram: "Ideogram",
    recraft: "Recraft V4", imagen: "Imagen 4", qwen: "Qwen", krea: "Krea 2",
  };
  const GEN_MODEL_DESCS = {
    auto: "Маккод подберёт модель сам",
    // image
    nanobanana2: "Google · быстрый фотореализм, 4K",
    gpt2: "OpenAI · точный по тексту, 4K",
    seedream: "ByteDance · эстетика по референсам",
    flux: "Black Forest · реализм и детали",
    turbo: "Pollinations · максимально быстро",
    mystic: "Magnific · фирменный фотореализм",
    cinematic: "Magnific · кинокадр, свет, 4K",
    ideogram: "графдизайн, надписи, логотипы",
    recraft: "вектор, бренд-стиль, иконки",
    imagen: "Google · чистый фотореализм",
    qwen: "Alibaba · быстрый, по референсам",
    krea: "художественная стилизация",
    // video
    veo: "Google · реализм, звук, синхрон губ",
    kling: "реалистичное видео до 4K, звук",
    hailuo: "MiniMax · живое движение",
    wan: "Alibaba · родной звук, старт/финал",
    seedance: "ByteDance · динамичные сцены",
    runway: "Gen-4.5 · кино, контроль движения",
    ltx: "до 4K, родной звук, длинные сцены",
    grok: "xAI · свежая модель",
  };
  const GEN_COUNTS = [1, 2, 4];
  const GEN_ASPECTS = ["auto", "16:9", "9:16", "1:1", "4:3", "3:4"];
  const GEN_LENGTHS = ["auto", "5s", "10s"];
  const GEN_SOUNDS = ["auto", "on", "off"];
  const GEN_SOUND_LABELS = { auto: "Авто", on: "Вкл", off: "Выкл" };
  function genDefault() { return { type: "image", source: "auto", model: "auto", count: 1, aspect: "auto", length: "auto", sound: "auto" }; }
  function genSourceOptions(g) { return g.type === "video" ? ["auto", "magnific"] : ["auto", "pollinations", "magnific"]; }
  function genIsMagnific(g) { return g.type === "video" || g.source === "magnific"; }
  function genModelOptions(g) {
    if (g.type === "video") return ["auto", "veo", "kling", "hailuo", "wan", "seedance", "runway", "grok", "ltx"];
    if (g.source === "magnific") return ["auto", "nanobanana2", "gpt2", "seedream", "flux", "mystic", "cinematic", "ideogram", "recraft", "imagen", "qwen", "grok", "krea"];
    if (g.source === "pollinations") return ["auto", "flux", "turbo"];
    return ["auto"];
  }
  function genModelLabel(m) { return GEN_MODEL_LABELS[m] || (m ? m[0].toUpperCase() + m.slice(1) : "Авто"); }
  function genCycle(arr, cur) { const i = arr.indexOf(cur); return arr[(i + 1) % arr.length]; }
  function genNormalize(g) {
    if (!genSourceOptions(g).includes(g.source)) g.source = "auto";
    if (!genModelOptions(g).includes(g.model)) g.model = "auto";
    if (!GEN_ASPECTS.includes(g.aspect) || !genIsMagnific(g)) g.aspect = "auto";
    if (!GEN_LENGTHS.includes(g.length) || g.type !== "video") g.length = "auto";
    if (!GEN_SOUNDS.includes(g.sound) || g.type !== "video") g.sound = "auto";
    return g;
  }
  function genPush() {
    refreshChips();
    sendCmd({ type: "settings", gen: state.gen });
  }

  // — Кредиты Magnific. Реальные цены приходят с бэка (gen_quote → simulate,
  //   кредиты НЕ тратит). Картинки: state.genQuote = {prices:{ключ:{cost,remaining}},
  //   pool, ts} — cost за 1 картинку, pool общий баланс плана, remaining у премиум-
  //   моделей их сублимит. Видео: state.genVQuote = {key, total, cost, pool, duration,
  //   ts} — total за весь клип, cost за секунду, key = связка модель|длина|звук|формат
  //   (цена зависит от всей связки, поэтому держим по ключу, а не одним блоком). —
  function genQuotePrices() { return (state.genQuote && state.genQuote.prices) || {}; }
  // Баланс плана — общий пул аккаунта Magnific (не зависит от типа/модели). Кэшируем
  // в state.genPool из ЛЮБОГО ответа quote (video или image), чтобы при раскрытии
  // поповера он был виден сразу, а не только после расчёта цены под конкретную связку.
  function genPool() { return state.genPool != null ? state.genPool : null; }
  function genModelCost(key) { const p = genQuotePrices()[key]; return p && typeof p.cost === "number" ? p.cost : null; }
  function genModelRemaining(key) { const p = genQuotePrices()[key]; return p && typeof p.remaining === "number" ? p.remaining : null; }
  // Видео-цена зависит от связки — ключ для кэша и сверки пришедшего ответа с выбором.
  function genVKey(g) { return [g.model, g.length, g.sound, g.aspect || "16:9"].join("|"); }
  function genQuoteApplicable(g) { return !!g && ((g.type === "image" && g.source === "magnific") || g.type === "video"); }
  function genEnsureQuote(g) {
    if (!genQuoteApplicable(g)) return;
    // Видео с полностью выбранной связкой — считаем цену клипа (video-quote).
    if (g.type === "video" && g.model !== "auto" && g.length !== "auto") {
      const key = genVKey(g);
      const fresh = state.genVQuote && state.genVQuote.key === key && (Date.now() - (state.genVQuote.ts || 0) < 60000);
      if (fresh || state.genQuoteLoading) return;
      state.genQuoteLoading = true;
      try { sendCmd({ type: "gen_quote", media: "video", model: g.model, length: g.length, sound: g.sound, aspect: g.aspect }); }
      catch (_) { state.genQuoteLoading = false; }
      return;
    }
    // Видео на auto: цену не считаем, но баланс нужен сразу при раскрытии — если пул
    // ещё неизвестен, дёрнем дешёвый image-quote (simulate вернёт pool). Знаем баланс — не дёргаем.
    if (g.type === "video" && state.genPool != null) return;
    const fresh = state.genQuote && (Date.now() - (state.genQuote.ts || 0) < 60000);
    if (fresh || state.genQuoteLoading) return;
    state.genQuoteLoading = true;
    try { sendCmd({ type: "gen_quote" }); } catch (_) { state.genQuoteLoading = false; }
  }
  // Видео-сводка: «Спишется N кр» (за весь клип) + «Баланс N кр». Цена под связку
  // модель+длина+звук+формат лежит в state.genVQuote, ключ сверяем с текущим выбором.
  // Буквенный бейдж модели для строки «Модель» (референс Magnific): первая буква
  // имени на детерминированном цвете из палитры. «Авто» — нейтральная звёздочка.
  function genModelIcon(model) {
    const label = (genModelLabel(model) || "?").trim();
    if (!model || model === "auto") return { ch: "✦", bg: "var(--accent-dim)" };
    const palette = ["#7c5cff", "#3b82f6", "#c45f3e", "#0ea5a4", "#d6457f", "#e0892b", "#6366f1", "#16a34a"];
    let h = 0;
    for (let i = 0; i < model.length; i++) h = (h * 31 + model.charCodeAt(i)) >>> 0;
    return { ch: (label[0] || "?").toUpperCase(), bg: palette[h % palette.length] };
  }
  function genVideoCreditRows(g) {
    const rows = [];
    if (g.model === "auto") {
      rows.push({ price: true, priceText: "выбери модель", info: true });
    } else if (g.length === "auto") {
      rows.push({ price: true, priceText: "выбери длину", info: true });
    } else {
      const key = genVKey(g);
      const v = state.genVQuote && state.genVQuote.key === key ? state.genVQuote : null;
      if (v && v.total != null) {
        const pool = genPool();
        const short = (pool != null && v.total > pool);
        rows.push({
          price: true, priceNum: v.total, warn: short,
          priceSub: v.cost != null ? `${v.cost}×${v.duration}с` : `${v.duration}с`,
          info: true,
        });
      } else if (state.genQuoteLoading) {
        rows.push({ price: true, priceText: "считаю…", info: true });
      }
    }
    // Баланс показываем всегда, как только пул известен — даже на auto/во время расчёта.
    const pool = genPool();
    if (pool != null) rows.push({ name: `Баланс: ${pool} кр`, desc: "", info: true });
    return rows;
  }
  // Некликабельные строки-сводка для поповера: «Спишется N кр» + «Баланс N кр».
  function genCreditRows(g) {
    if (g.type === "video") return genVideoCreditRows(g);
    const rows = [];
    if (state.genQuoteLoading && !state.genQuote) {
      rows.push({ price: true, priceText: "считаю…", info: true });
    } else {
      const cost = genModelCost(g.model);   // за 1 картинку
      if (g.model === "auto") {
        rows.push({ price: true, priceText: "выбери модель", info: true });
      } else if (cost != null) {
        const total = cost * g.count;
        const rem = genModelRemaining(g.model);
        const short = (rem != null && total > rem);
        rows.push({
          price: true, priceNum: total, warn: short,
          priceSub: g.count > 1 ? `${cost}×${g.count}` : "",
          info: true,
        });
      }
    }
    const pool = genPool();
    if (pool != null) {
      const rem = genModelRemaining(g.model);
      let desc = "";
      if (g.model !== "auto" && rem != null && rem < pool) desc = `осталось ${rem}`;
      rows.push({ name: `Баланс: ${pool} кр`, desc, info: true });
    }
    return rows;
  }

  function renderGenPopover() {
    if (!chipPopoverEl) chipPopoverEl = document.getElementById("chip-popover");
    if (!chipPopoverEl) return;
    const g = genNormalize(state.gen || genDefault());
    genEnsureQuote(g);
    // Память прокрутки: запоминаем позицию текущего вида; восстановим её только
    // если вид не сменился (перещёлкивание опций), иначе список прыгал наверх.
    const prevView = chipPopoverEl.dataset.genView || "main";
    const prevScrollEl = chipPopoverEl.querySelector(".gen-scroll");
    if (prevScrollEl) genScrollTop = prevScrollEl.scrollTop;
    if (genPopoverView === "model") {
      renderGenRows(genModelRows(g));
      chipPopoverEl.dataset.genView = "model";
      restoreGenScroll(prevView, "model");
      return;
    }
    const mico = genModelIcon(g.model);
    // Описания строк-настроек намеренно пустые: значение уже в названии,
    // двухстрочные пункты делали попап громоздким (просьба «поменьше и полегче»).
    const rows = [
      { name: `Тип: ${GEN_TYPE_LABELS[g.type]}`, desc: "",
        run: () => { g.type = genCycle(GEN_TYPES, g.type); genNormalize(g); state.gen = g; genPush(); renderGenPopover(); } },
      { name: `Источник: ${GEN_SOURCE_LABELS[g.source]}${g.source === "auto" ? "" : (g.source === "pollinations" ? " · бесплатно" : " · премиум")}`,
        desc: "",
        run: () => { g.source = genCycle(genSourceOptions(g), g.source); genNormalize(g); state.gen = g; genPush(); renderGenPopover(); } },
      { name: `<span class="gen-mico" style="background:${mico.bg}">${mico.ch}</span>Модель: ${genModelLabel(g.model)}`,
        desc: "",
        run: () => { if (genModelOptions(g).length > 1) genPopoverView = "model"; renderGenPopover(); } },
    ];
    if (genIsMagnific(g)) {
      rows.push({ name: `Соотношение: ${g.aspect === "auto" ? "Авто" : g.aspect}`, desc: "",
        run: () => { g.aspect = genCycle(GEN_ASPECTS, g.aspect); state.gen = g; genPush(); renderGenPopover(); } });
    }
    if (g.type === "video") {
      rows.push({ name: `Длина: ${g.length === "auto" ? "Авто" : g.length}`, desc: "",
        run: () => { g.length = genCycle(GEN_LENGTHS, g.length); state.gen = g; genPush(); renderGenPopover(); } });
      rows.push({ name: `Звук: ${GEN_SOUND_LABELS[g.sound]}`, desc: "",
        run: () => { g.sound = genCycle(GEN_SOUNDS, g.sound); state.gen = g; genPush(); renderGenPopover(); } });
    } else {
      rows.push({ name: `Количество: ${g.count}`, desc: "",
        run: () => { g.count = genCycle(GEN_COUNTS, g.count); state.gen = g; genPush(); renderGenPopover(); } });
    }
    if (genQuoteApplicable(g)) {
      genCreditRows(g).forEach((r) => rows.push(r));
    }
    if (state.gen) {
      rows.push({ name: "Сбросить", desc: "", reset: true,
        run: () => { state.gen = null; refreshChips(); sendCmd({ type: "settings", gen: null }); hideChipPopover(); } });
    }
    renderGenRows(rows);
    chipPopoverEl.dataset.genView = "main";
    restoreGenScroll(prevView, "main");
  }

  // Восстанавливает прокрутку списка опций Ген после перерисовки: тот же вид —
  // вернуть genScrollTop; сменился (настройки↔список моделей) — показать сверху.
  function restoreGenScroll(prevView, curView) {
    if (prevView !== curView) { genScrollTop = 0; return; }
    const sc = chipPopoverEl && chipPopoverEl.querySelector(".gen-scroll");
    if (sc) sc.scrollTop = genScrollTop;
  }

  // Список моделей как под-вид поповера Ген: «‹ Назад» + модели с лирикой,
  // активная помечена ✓. Тап по модели выбирает и возвращает к настройкам.
  function genModelRows(g) {
    const rows = [{
      name: "‹ Назад", desc: "к настройкам генерации", back: true,
      run: () => { genPopoverView = null; renderGenPopover(); },
    }];
    genModelOptions(g).forEach((m) => {
      const cost = genModelCost(m);
      let desc = GEN_MODEL_DESCS[m] || "";
      if (m !== "auto" && cost != null) desc = desc ? `${desc} · ${cost} кр` : `${cost} кр`;
      rows.push({
        name: (m === g.model ? "✓ " : "") + genModelLabel(m),
        desc,
        active: m === g.model,
        run: () => { g.model = m; state.gen = g; genPush(); genPopoverView = null; renderGenPopover(); },
      });
    });
    return rows;
  }

  // Общий рендер строк поповера Ген — и для настроек, и для списка моделей.
  function renderGenRows(rows) {
    // Спишется/Баланс/Сбросить (info+reset) уезжают в закреплённый низ поповера —
    // .gen-footer вне области скролла (flex-shrink:0); список опций .gen-scroll
    // над ним прокручивается, футер намертво у нижней кромки окна поповера.
    let mainHtml = "";
    let balanceHtml = "";   // info-строки кроме цены (Баланс) — отдельной строкой над экшенами
    let priceHtml = "";     // крупный ценник «✦ N кр»
    let resetHtml = "";     // кнопка «Сбросить»
    rows.forEach((r, i) => {
      if (r.price) {
        const warn = !!r.warn;
        const muted = (r.priceNum == null);   // плейсхолдер («считаю…», «выбери модель»)
        const main = muted ? (r.priceText || "—") : String(r.priceNum);
        const sub = warn ? "не хватит" : (r.priceSub || "");
        priceHtml =
          `<div class="gen-price${warn ? " gen-price-warn" : ""}${muted ? " gen-price-muted" : ""}">` +
            `<span class="gen-price-spark">✦</span>` +
            `<span class="gen-price-main">${main}</span>` +
            (muted ? "" : `<span class="gen-price-unit">кр</span>`) +
            (sub ? `<span class="gen-price-sub">${sub}</span>` : "") +
          `</div>`;
        return;
      }
      let cls = "slash-suggest-row";
      if (r.reset) cls += " gen-reset";
      if (r.active) cls += " gen-active";
      if (r.back) cls += " gen-back";
      if (r.info) cls += " gen-info";
      if (r.warn) cls += " gen-warn";
      const descHtml = r.desc ? `<div class="slash-suggest-desc">${r.desc}</div>` : "";
      const rowHtml = `<div class="${cls}" data-idx="${i}"><div class="slash-suggest-name">${r.name}</div>${descHtml}</div>`;
      if (r.reset) resetHtml += rowHtml;
      else if (r.info) balanceHtml += rowHtml;
      else mainHtml += rowHtml;
    });
    // Есть ценник → «Сбросить» компактной кнопкой рядом; нет — «Сбросить» во всю ширину, как было.
    const actionsHtml = priceHtml ? `<div class="gen-actions">${priceHtml}${resetHtml}</div>` : resetHtml;
    const footerHtml = balanceHtml + actionsHtml;
    chipPopoverEl.innerHTML = `<div class="gen-scroll">${mainHtml}</div>` + (footerHtml ? `<div class="gen-footer">${footerHtml}</div>` : "");
    chipPopoverEl.classList.remove("hidden", "closing");
    chipPopoverEl.dataset.anchor = "gen";
    chipPopoverEl.querySelectorAll(".slash-suggest-row").forEach((row) => {
      const i = parseInt(row.getAttribute("data-idx") || "0", 10);
      const r = rows[i];
      if (!r || r.info) return;   // info-строки (цена/баланс) некликабельны
      let fired = false;
      const trigger = () => {
        if (fired) return;
        fired = true;
        haptic.tap();
        try { r.run && r.run(); } catch (err) { console.error("gen popover action failed", err); }
      };
      row.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
      row.addEventListener("pointerup",   (e) => { e.stopPropagation(); trigger(); });
      row.addEventListener("click",       (e) => { e.stopPropagation(); trigger(); });
    });
  }

  function openChipPopoverFor(kind, anchorChip) {
    haptic.select();
    hideSlashSuggest(true);
    if (!chipPopoverEl) chipPopoverEl = document.getElementById("chip-popover");
    if (chipPopoverEl && !chipPopoverEl.classList.contains("hidden")) {
      const sameAnchor = chipPopoverEl.dataset.anchor === kind;
      hideChipPopover();
      // Повторный тап по тому же чипу (вкл. Ген) — закрыть. Для Ген это стабильно:
      // chip-gen исключён из dismiss-на-pointerdown, поэтому click всегда видит
      // попап открытым и честно гасит его (раньше «через раз» — pointerdown успевал
      // закрыть до click, а click переоткрывал).
      if (sameAnchor) { haptic.bump(); return; }
    }
    if (chipPopoverEl) chipPopoverEl.dataset.anchor = kind;

    if (kind === "context") {
      const cmd = SLASH_COMMANDS.find((c) => c.name === "compact");
      const items = [{
        key: "compact",
        label: "/compact",
        desc: cmd ? cmd.desc : "сжать контекст",
        run: () => { if (cmd && cmd.run) { pushCommandTrace(cmd); cmd.run(); } },
      }];
      renderChipPopover(items, null);
      return;
    }
    if (kind === "gen") { genPopoverView = null; renderGenPopover(); return; }
    let map = null, current = null, descMap = null;
    if (kind === "model")  { map = state.models;  current = state.model;  descMap = MODEL_DESCS; }
    if (kind === "effort") { map = state.efforts; current = state.effort; descMap = EFFORT_DESCS; }
    if (kind === "view")   { map = state.views;   current = state.view;   descMap = VIEW_DESCS; }
    if (!map) return;
    const items = Object.entries(map).map(([key, label]) => ({
      key,
      label,
      desc: (descMap && descMap[key]) || "",
      run: () => {
        if (state[kind] !== undefined) state[kind] = key;
        refreshChips();
        const payload = { type: "settings" };
        payload[kind] = key;
        sendCmd(payload);
      },
    }));
    renderChipPopover(items, current);
  }

  function hideSlashSuggest(immediate) {
    if (!slashSuggestEl) slashSuggestEl = document.getElementById("slash-suggest");
    if (!slashSuggestEl) return;
    slashSuggestList = [];
    slashSuggestIdx = 0;
    if (slashSuggestEl.classList.contains("hidden")) return;
    if (immediate) {
      slashSuggestEl.classList.remove("closing");
      slashSuggestEl.classList.add("hidden");
      slashSuggestEl.innerHTML = "";
      return;
    }
    slashSuggestEl.classList.add("closing");
    const onEnd = () => {
      slashSuggestEl.removeEventListener("animationend", onEnd);
      if (!slashSuggestEl.classList.contains("closing")) return;
      slashSuggestEl.classList.remove("closing");
      slashSuggestEl.classList.add("hidden");
      slashSuggestEl.innerHTML = "";
    };
    slashSuggestEl.addEventListener("animationend", onEnd, { once: true });
  }

  function renderSlashSuggest() {
    if (!slashSuggestEl) slashSuggestEl = document.getElementById("slash-suggest");
    if (!slashSuggestEl) return;
    if (!slashSuggestList.length) { hideSlashSuggest(); return; }
    let html = "";
    slashSuggestList.forEach((c, i) => {
      const cls = i === slashSuggestIdx ? "slash-suggest-row active" : "slash-suggest-row";
      const arg = c.needsArg ? ` <i>&lt;текст&gt;</i>` : "";
      const longDesc = c.details || c.desc || "";
      html += `<div class="${cls}" data-idx="${i}"><div class="slash-suggest-name">/${c.name}${arg}</div><div class="slash-suggest-desc">${longDesc}</div></div>`;
    });
    html += `<div class="slash-suggest-row slash-suggest-more" data-action="more"><div class="slash-suggest-name">подробно о командах</div><div class="slash-suggest-desc">открыть полный список с описаниями</div></div>`;
    slashSuggestEl.innerHTML = html;
    slashSuggestEl.classList.remove("hidden", "closing");
    slashSuggestEl.querySelectorAll(".slash-suggest-row").forEach((row) => {
      row.addEventListener("mousedown", (e) => {
        e.preventDefault();
        if (row.getAttribute("data-action") === "more") {
          hideSlashSuggest();
          showSlashHelp();
          return;
        }
        const i = parseInt(row.getAttribute("data-idx") || "0", 10);
        slashSuggestIdx = i;
        applySlashSuggest();
      });
    });
  }

  function updateSlashSuggest() {
    const raw = inputEl.value;
    if (!raw || !raw.startsWith("/") || raw.startsWith("//")) { hideSlashSuggest(); return; }
    const m = raw.match(/^\/([a-zA-Z][\w-]*)?$/);
    if (!m) { hideSlashSuggest(); return; }
    const q = (m[1] || "").toLowerCase();
    slashSuggestList = SLASH_COMMANDS.filter((c) => !q || c.name.startsWith(q));
    slashSuggestIdx = 0;
    renderSlashSuggest();
  }

  // v983: @-меншены прикреплённых файлов. После символа @ (в начале строки
  // или после пробела/переноса) показываем chip-popover со списком текущих
  // state.attachments. Каждый пункт = «@N · имя_файла». Тап подставляет
  // «@N » в текст. Сервер видит сырое сообщение с упоминаниями + массив
  // attachments — соответствие N→файл по порядку в attach-row.
  function isMentionPopoverOpen() {
    if (!chipPopoverEl) chipPopoverEl = document.getElementById("chip-popover");
    return !!(chipPopoverEl && !chipPopoverEl.classList.contains("hidden") && chipPopoverEl.dataset.anchor === "mention");
  }
  function hideMentionPopover(immediate) {
    if (!isMentionPopoverOpen()) return;
    hideChipPopover(immediate);
  }
  function updateMentionSuggest() {
    if (!inputEl) { hideMentionPopover(true); return; }
    const raw = inputEl.value || "";
    // Быстрый выход без чтения selectionStart (forced reflow): нет '@' → меншена быть не может.
    if (raw.indexOf("@") < 0) { hideMentionPopover(); return; }
    const pos = inputEl.selectionStart != null ? inputEl.selectionStart : raw.length;
    const left = raw.slice(0, pos);
    const m = left.match(/(?:^|\s)@([^\s@]*)$/);
    if (!m) { hideMentionPopover(); return; }
    const atts = state.attachments || [];
    if (!atts.length) { hideMentionPopover(); return; }
    const q = (m[1] || "").toLowerCase();
    const filtered = atts
      .map((a, idx) => ({ n: idx + 1, a }))
      .filter(({ n, a }) => !q || String(n).startsWith(q) || (a.name || "").toLowerCase().includes(q));
    if (!filtered.length) { hideMentionPopover(); return; }
    hideSlashSuggest(true);
    if (!chipPopoverEl) chipPopoverEl = document.getElementById("chip-popover");
    if (chipPopoverEl) chipPopoverEl.dataset.anchor = "mention";
    const items = filtered.map(({ n, a }) => ({
      key: `mention-${n}`,
      label: `@${n} · ${a.name || "файл"}`,
      desc: a.size ? fmtSize(a.size) : "",
      run: () => insertMention(n),
    }));
    renderChipPopover(items, null);
  }
  function insertMention(n) {
    if (!inputEl) return;
    const raw = inputEl.value || "";
    const pos = inputEl.selectionStart != null ? inputEl.selectionStart : raw.length;
    const left = raw.slice(0, pos);
    const right = raw.slice(pos);
    const newLeft = left.replace(/@[^\s@]*$/, `@${n} `);
    if (newLeft === left) return;
    inputEl.value = newLeft + right;
    const newPos = newLeft.length;
    try { inputEl.setSelectionRange(newPos, newPos); } catch (_) {}
    if (inputEl.parentElement) inputEl.parentElement.classList.add("has-content");
    inputEl.focus();
    inputEl.dispatchEvent(new Event("input", { bubbles: true }));
  }

  function moveSlashSuggest(delta) {
    if (!slashSuggestList.length) return;
    slashSuggestIdx = (slashSuggestIdx + delta + slashSuggestList.length) % slashSuggestList.length;
    renderSlashSuggest();
  }

  function applySlashSuggest() {
    if (!slashSuggestList.length) return;
    const c = slashSuggestList[slashSuggestIdx];
    inputEl.value = `/${c.name}${c.needsArg ? " " : ""}`;
    if (inputEl.parentElement) inputEl.parentElement.classList.add("has-content");
    autoResize();
    hideSlashSuggest();
    if (c.needsArg) {
      inputEl.focus();
    } else {
      maybeRunSlashCommand();
    }
  }

  // ===== send message =====
  function send() {
    if (maybeRunSlashCommand()) return;
    const text = inputEl.value.trim();
    const atts = state.attachments.map((a) => a.path);
    if (!text && !atts.length) return;
    state.stopSuppressUntil = 0;  // реально отправляем — снять подавление «думаю» от прошлого Stop
    if (!state.ready) { toast("нет связи"); haptic.err(); return; }
    if (state.pendingUploads > 0 || state.uploadJobs.length > 0) { toast("ещё загружаю файлы"); haptic.warn(); return; }

    if (state.startMode) {
      // на стартовой странице отправка = создаём новый чат и шлём туда
      if (state.pendingNewChatMsg) {
        // уже жмём «отправить» в момент создания чата — игнорим, иначе перезатрём первый текст и он потеряется
        toast("ещё создаю чат");
        haptic.warn();
        return;
      }
      const bubbleAtts = state.attachments.map((a) => ({
        name: a.name,
        previewUrl: a.previewUrl || null,
        url: a.url || null,
        size: a.size || 0,
      }));
      state.pendingNewChatMsg = { text, atts: [...atts], bubbleAtts };
      inputEl.value = "";
      if (inputEl.parentElement) inputEl.parentElement.classList.remove("has-content");
      autoResize(true);
      state.pendingBusy = true;
      updateBusyUI();
      haptic.bump();
      // attachments-снимок передан в bubble — больше не наши, очищаем без revoke.
      state.attachments = [];
      renderAttachRow();
      // Оптимистично рисуем пузырь и убираем стартовую заставку, не дожидаясь
      // ответа сервера на thread_new: иначе до создания треда на экране висит
      // логотип «С чего начнём?» и кажется, что сообщение не отправилось.
      // startMode держим true (серверный флоу создания треда не трогаем),
      // optimisticRendered не даст flush'у перерисовать пузырь повторно.
      try {
        const _sp = chatEl.querySelector(".start-page");
        if (_sp) _sp.remove();
        document.body.classList.remove("start-shown");
        state.userScrolledUp = false;
        pushMsg("user", text, "ты", Date.now(), bubbleAtts.length ? { attachments: bubbleAtts } : undefined);
        if (state.pendingNewChatMsg) state.pendingNewChatMsg.optimisticRendered = true;
      } catch (_) {}
      sendCmd({ type: "thread_new" });
      return;
    }

    const outText = (voiceMode.active ? VOICE_MODE_PREFIX : "") + text;
    const payload = { type: "message", text: outText };
    if (atts.length) payload.attachments = atts;
    // Дёрганая LTE: сокет мог закрыться ровно в момент тапа. Не теряем сообщение
    // и не заставляем перепечатывать — кладём в outbox, рисуем пузырь как при живой
    // связи, форсим немедленный реконнект. flushOutbox дошлёт его по "ready" (сервер
    // шлёт message в текущий серверный тред, который встаёт из auth-payload; если за
    // время обрыва юзер сменил тред — flushOutbox вернёт текст в инпут, см. ниже).
    let _queuedOffline = false;
    if (!sendCmd(payload)) {
      state.outbox.push({ payload, thread_id: state.currentThread });
      _queuedOffline = true;
      scheduleReconnect(true);
    }

    clearEmptyHint();
    const bubbleAtts = state.attachments.map((a) => ({
      name: a.name,
      previewUrl: a.previewUrl || null,
      url: a.url || null,
      size: a.size || 0,
    }));
    // GPT-стиль: камеру замораживаем СРАЗУ (userScrolledUp=true ДО pushMsg), чтобы
    // scrollBottom внутри pushMsg(user) не пинил вниз, а первый чанк ответа не дёрнул
    // камеру за собой. Дальше своя логика уводит моё сообщение к верху (см. ниже).
    state.userScrolledUp = true;
    const _userDiv = pushMsg("user", text, "ты", Date.now(), bubbleAtts.length ? { attachments: bubbleAtts } : undefined);
    inputEl.value = "";
    if (inputEl.parentElement) inputEl.parentElement.classList.remove("has-content");
    state.attachments = [];
    renderAttachRow();
    autoResize(true);
    {
      const _tid = state.currentThread;
      if (_tid && _tid !== "favorites") {
        setDraftLocal(_tid, "");
        flushDraftToServer(_tid, "");
      }
    }
    if (!_queuedOffline && state.currentThread && state.currentThread !== "favorites") {
      const tid = state.currentThread;
      state.recentlyFinished.delete(tid);
      state.stoppedThreads.delete(tid);
      const wasBusy = state.busyThreads.has(tid);
      state.busyThreads.add(tid);
      // Раньше тут стоял markBusyVerified — это было оптимистично:
      // sendCmd по WS — fire-and-forget, доставка не подтверждена. Если message не дошёл
      // (TG-WebView заснул, сокет полу-мёртв, сервер моргнул) — UI висел "thinking" навсегда.
      // Теперь: если тред ещё не работает, кладём в unverifiedBusy ("waiting" в топ-баре)
      // и ставим короткий watchdog. Сервер шлёт `running` сразу при получении message —
      // через enterBusyIfNeeded → markBusyVerified снимет unverified, UI станет "thinking".
      // Если за 4с не пришло — считаем, что не доехало, гасим busy и сообщаем юзеру.
      if (!wasBusy) {
        state.unverifiedBusy.add(tid);
        const oldTimer = state.unverifiedBusyTimers.get(tid);
        if (oldTimer) clearTimeout(oldTimer);
        const timer = setTimeout(() => {
          state.unverifiedBusyTimers.delete(tid);
          if (!state.unverifiedBusy.has(tid)) return;
          dbg("send: 4s ack-timeout, evict unverified", { tid });
          clearBusyState(tid);
          if (tid === state.currentThread) updateBusyUI();
          renderAllThreadLists();
          toast("сервер не подтвердил отправку");
          haptic.warn();
        }, 4000);
        state.unverifiedBusyTimers.set(tid, timer);
      }
    }
    state.unreadThreads.delete(state.currentThread);
    state.unreadCounts.delete(state.currentThread);
    state.lastBubbleType.delete(state.currentThread);
    saveUnread();
    renderThreads();
    updateBusyUI();
    haptic.bump();
    // v941: если push-reload был отложен на typing-gate — теперь поле пустое, ребутимся.
    try { flushPendingPushReload(); } catch (_) {}
    // мы только что отправили — палец-на-чате игнорируем (мог залипнуть от touchend timer)
    state.userTouching = false;
    if (state.userTouchingTimer) {
      clearTimeout(state.userTouchingTimer);
      state.userTouchingTimer = null;
    }
    // v1065: ChatGPT-style — моё свежее сообщение уезжает к ВЕРХУ экрана, камера
    // замирает и НЕ следует за стримом ответа. Нижний turn-спейсер резервирует
    // место, чтобы сообщение дотянулось к верху даже когда ответа ещё нет; по мере
    // роста ответа спейсер схлопывается (см. startTurnAnchor/updateTurnSpacer).
    // Непрочитанное копится в бейдже стрелки вниз (bumpUnread в pushMsg).
    if (_userDiv) startTurnAnchor(_userDiv);
    // На мобиле/в IPA сворачиваем клавиатуру при отправке (Кирилл: «при отправке
    // клавиатура должна автоматом свернуться») и СРАЗУ обнуляем --kb. Иначе RAF-скролл
    // ниже посчитал бы посадку по kb-active-ветке (25% высоты), а через 60мс
    // делегированный focusout дёрнул бы setKb(0) — layout прыгнул бы и сообщение
    // уехало. Синхронный setKb(0) убирает этот промежуточный прыжок.
    if (isMobilePlatform) {
      try { inputEl.blur(); } catch (_) {}
      try { setKb(0); } catch (_) {}
    }
    requestAnimationFrame(() => {
      if (!_userDiv || !chatEl) return;
      updateTurnSpacer();                 // спейсер учитывает уже применённый layout
      // Та же посадка, что у стрелки-вверх (scroll-up-btn): моё сообщение встаёт
      // на ту же высоту (Кирилл: «должно улетать на высоту как при нажатии на
      // стрелочку наверх»). PAD/topbar/pinBar/kb-ветка — копия её формулы offTop.
      const PAD = 12;
      const isGlass = document.documentElement.classList.contains("theme-glass");
      const topbarEl = document.getElementById("topbar");
      const pinBarEl = document.getElementById("pin-bar");
      const computeOffTop = (cr) => {
        const topbarH = isGlass && topbarEl ? topbarEl.getBoundingClientRect().height : 0;
        // pin-bar — absolute-overlay поверх верха #chat ВО ВСЕХ темах (см.
        // `.pin-bar{position:absolute; top:var(--topbar-h)}` в styles.css), поэтому
        // его высоту вычитаем всегда. Без этого (раньше — гейт isGlass) GPT-скролл
        // в не-glass темах сажал моё сообщение под закреплённое — видно сквозь blur.
        // topbarH остаётся под isGlass: в остальных темах топбар sticky-в-потоке,
        // #chat и так начинается под ним, вычитать не нужно.
        const pinBarH = pinBarEl && !pinBarEl.classList.contains("hidden")
          ? pinBarEl.getBoundingClientRect().height : 0;
        const kb = parseInt(getComputedStyle(document.documentElement).getPropertyValue("--kb")) || 0;
        const visibleH = cr.height - kb;
        return (document.body.classList.contains("kb-active") && visibleH > 120)
          ? Math.max(PAD + topbarH + pinBarH, Math.round(visibleH * 0.25))
          : PAD + topbarH + pinBarH;
      };
      const cRect = chatEl.getBoundingClientRect();
      const offTop = computeOffTop(cRect);
      const tRect = _userDiv.getBoundingClientRect();
      const offset = tRect.top - cRect.top + chatEl.scrollTop;
      const top = Math.max(0, offset - offTop);
      // touch-метка на старте GPT-скролла: если к моменту досадки она изменилась
      // (юзер коснулся ленты, чтобы листать) — settle НЕ перебивает его скролл.
      const _touchAtSend = state.lastTouchAt || 0;
      state.programmaticScroll = (state.programmaticScroll || 0) + 1;
      const dur = smoothScrollChatTo(top);
      // Досадка как у scroll-up-btn: пока шёл easing, клава могла довернуть layout
      // (или приехал первый чанк ответа и спейсер схлопнулся) — пере-наводим жёстко.
      const settle = () => {
        if (!_userDiv || !chatEl) return;
        // Юзер сам начал листать (палец на ленте или коснулся её после старта) —
        // не дёргаем scrollTop обратно к моему сообщению, иначе «промотал вниз →
        // бросило наверх». Снимаем счётчик программного скролла и выходим.
        if (state.userTouching || (state.lastTouchAt || 0) !== _touchAtSend) {
          state.programmaticScroll = Math.max(0, state.programmaticScroll - 1);
          try { updateScrollDownBtn(); } catch (_) {}
          return;
        }
        const c2 = chatEl.getBoundingClientRect();
        const t2 = _userDiv.getBoundingClientRect();
        const wantTop = (t2.top - c2.top + chatEl.scrollTop) - computeOffTop(c2);
        if (Math.abs(chatEl.scrollTop - wantTop) > 4) {
          chatEl.scrollTop = Math.max(0, wantTop);
        }
        state.programmaticScroll = Math.max(0, state.programmaticScroll - 1);
        state.userScrolledUp = true;   // держим заморозку до ручного жеста вниз
        try { updateScrollDownBtn(); } catch (_) {}
      };
      setTimeout(settle, (dur || 0) + 80);
    });
  }

  let _autoResizeRaf = 0;
  let _lastResizeLen = -1;
  let _lastResizeNL = -1;
  function autoResize(force) {
    const v = inputEl.value;
    const len = v.length;
    const nl = (v.match(/\n/g) || []).length;
    // NEW-D: цветной текст mirror'а — синхронно, на КАЖДЫЙ вызов (= каждый
    // keystroke), ДО любого rAF. Так он никогда не отстаёт от нативной каретки.
    // Дёшево: без чтения layout, только перезапись textContent существующих span'ов.
    try { syncInputMirrorText(); } catch (_) {}
    // Пропускаем reflow только если длина и кол-во переносов строк не изменились
    // (повтор того же значения). Любое изменение длины — рост, сжатие, или
    // изменение nl — триггерит пересчёт. rAF ниже дебаунсит частые keystroke'и.
    if (!force && len === _lastResizeLen && nl === _lastResizeNL) {
      // Высота не поменяется (та же длина/переносы), текст уже синхронизирован
      // выше — выходим без reflow.
      return;
    }
    _lastResizeLen = len;
    _lastResizeNL = nl;
    if (_autoResizeRaf) cancelAnimationFrame(_autoResizeRaf);
    _autoResizeRaf = requestAnimationFrame(() => {
      _autoResizeRaf = 0;
      const wrap = inputEl.parentElement;
      // Стартовая высота для transition. 'auto'↔px CSS не интерполирует,
      // поэтому меряем без анимации, возвращаем prev и только потом ставим финальную.
      const prevHeight = inputEl.style.height || (inputEl.getBoundingClientRect().height + "px");
      const prevTransition = inputEl.style.transition;
      inputEl.style.transition = "none";
      // Двухпроходный замер: сначала меряем без is-multiline (чистая высота
      // одно/много-строчного текста), потом, если переходим в multiline,
      // переснимаем — у textarea border-box, и padding-bottom:40px съест
      // часть высоты, иначе текст обрежется.
      if (wrap) wrap.classList.remove("is-multiline");
      inputEl.style.height = "auto";
      const sh1 = inputEl.scrollHeight;
      const isMulti = sh1 >= 84;
      if (wrap) wrap.classList.toggle("is-multiline", isMulti);
      let h;
      if (isMulti) {
        inputEl.style.height = "auto";
        const sh2 = inputEl.scrollHeight;
        h = Math.min(200, Math.max(40, sh2));
        inputEl.style.overflowY = sh2 > 200 ? "auto" : "hidden";
      } else {
        h = Math.min(200, Math.max(40, sh1));
        inputEl.style.overflowY = sh1 > 200 ? "auto" : "hidden";
      }
      // Возвращаем стартовую высоту, форсим reflow, снимаем 'none' —
      // финальный setHeight уже едет по transition из styles.css.
      inputEl.style.height = prevHeight;
      void inputEl.offsetHeight;
      inputEl.style.transition = prevTransition;
      inputEl.style.height = h + "px";
      // Высота композера изменилась → чипы quick-reply сдвинулись по вертикали
      // относительно пузырей за ними. Пересчитываем фоны чипов ТОЛЬКО здесь
      // (не на каждый keystroke — см. input-listener): обычная печать без
      // переноса строки высоту не меняет, reflow по .msg.user не идёт.
      try {
        const _prevH = parseFloat(prevHeight) || 0;
        if (Math.abs(h - _prevH) > 0.5) scheduleChipBgUpdate();
      } catch (_) {}
      // После пересчёта высоты — догнать mirror.
      try { syncInputMirror(); } catch (_) {}
    });
  }

  // v951: textarea высота пин-pin'илась px-значением и не пересчитывалась
  // при resize окна (orientationchange, появление/уход клавиатуры, drag
  // splitter сайдбара). Кирилл: «поле ввода кривое постоянно ломается».
  // Дёргаем autoResize(true) на каждое изменение viewport — за один кадр
  // textarea пересчитает scrollHeight под новую ширину и встанет корректно.
  try {
    const resyncInput = () => {
      try { if (typeof autoResize === "function") autoResize(true); } catch (_) {}
    };
    window.addEventListener("resize", resyncInput, { passive: true });
    window.addEventListener("orientationchange", () => {
      // orientationchange прилетает ДО reflow — двойной rAF чтобы дождаться
      // реальных размеров после поворота.
      requestAnimationFrame(() => requestAnimationFrame(resyncInput));
    }, { passive: true });
    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", resyncInput, { passive: true });
    }
  } catch (_) {}

  function insertSlashCommand(name) {
    if (!name) return;
    modal.classList.add("hidden");
    const cmd = "/" + String(name).replace(/^\/+/, "") + " ";
    inputEl.value = cmd;
    if (inputEl.parentElement) inputEl.parentElement.classList.add("has-content");
    autoResize(true);
    inputEl.focus();
    try {
      const end = inputEl.value.length;
      inputEl.setSelectionRange(end, end);
    } catch (_) {}
    haptic.ok();
  }

  // ===== events =====
  // iOS WKWebView: при открытой клаве tap по send делал blur у inputEl → клава
  // начинала сворачиваться → composer уезжал вниз → click промахивался мимо
  // новой позиции кнопки. Превентим default на pointerdown/mousedown, пока
  // input в фокусе — фокус не теряется, клава не двигается, click долетает.
  const _keepInputFocus = (e) => {
    // iOS WKWebView: preventDefault на pointerdown с pointerType="touch" глотает
    // синтетический click у <button> → маскот не нажимается, когда поле в фокусе
    // (т.е. когда набран текст). На touch фокус и так не теряется при тапе по
    // кнопке — превентим default только для мыши (десктоп), не для пальца.
    if (e && e.pointerType === "touch") return;
    if (document.activeElement === inputEl) {
      try { e.preventDefault(); } catch (_) {}
    }
  };
  sendBtn.addEventListener("pointerdown", _keepInputFocus);
  sendBtn.addEventListener("mousedown", _keepInputFocus);
  sendBtn.addEventListener("click", () => {
    // v935: в режиме is-stop (thinking) #send работает как STOP — морф из инвейдера.
    if (sendBtn.classList.contains("is-stop")) {
      haptic.knock();
      sendCmd({ type: "stop" });
      optimisticStopUI();
      return;
    }
    haptic.tap();
    if (state.recording) { stopRec(); return; }
    send();
  });
  stopBtn.addEventListener("click", () => { haptic.knock(); sendCmd({ type: "stop" }); optimisticStopUI(); });
  chipModel.addEventListener("click",  () => openChipPopoverFor("model", chipModel));
  chipEffort.addEventListener("click", () => openChipPopoverFor("effort", chipEffort));
  chipView.addEventListener("click",   () => openChipPopoverFor("view", chipView));
  if (chipGen) chipGen.addEventListener("click", () => openChipPopoverFor("gen", chipGen));
  if (chipContext) chipContext.addEventListener("click", () => openChipPopoverFor("context", chipContext));
  chipSlash?.addEventListener("click", () => {
    if (!slashSuggestEl) slashSuggestEl = document.getElementById("slash-suggest");
    const visible = slashSuggestEl && !slashSuggestEl.classList.contains("hidden");
    if (visible) { haptic.bump(); hideSlashSuggest(); return; }
    haptic.tap();
    slashSuggestList = SLASH_COMMANDS.slice();
    slashSuggestIdx = 0;
    renderSlashSuggest();
  });
  // Десктоп-аналог свайпа ↑ от инпута — тоггл .open у #fav-react-row.
  // На мобиле кнопка скрыта CSS'ом (там жест), на десктопе видна справа от /команды.
  chipReact?.addEventListener("click", () => {
    if (!favReactRow) return;
    haptic.tap();
    favReactRow.classList.toggle("open");
    chipReact.classList.toggle("active", favReactRow.classList.contains("open"));
  });
  function copySessionPath() {
    if (!state.currentSession) return;
    const path = sessionPathFor(state.currentSession);
    try {
      navigator.clipboard.writeText(path);
      toast("путь скопирован");
      haptic.tap();
    } catch (_) {}
  }
  if (chipSession) chipSession.addEventListener("click", copySessionPath);

  // ===== Topbar title menu / inline rename =====
  // Короткий тап по заголовку → выпадает меню (ID треда + сгенерировать название).
  // Длинный тап (~480мс) → inline-редактирование названия прямо в шапке.
  let topbarMenuClosing = false;
  let topbarLongPressTimer = 0;
  let topbarLongPressFired = false;
  let topbarPointerDown = false;
  let topbarPointerStart = null;
  let topbarRegenerating = false;

  function isTopbarMenuOpen() {
    return !!topbarMenuEl && !topbarMenuEl.classList.contains("hidden");
  }

  function closeTopbarMenu(immediate) {
    if (!topbarMenuEl) return;
    if (topbarMenuEl.classList.contains("hidden")) {
      topbarTitle && topbarTitle.setAttribute("aria-expanded", "false");
      return;
    }
    if (immediate) {
      topbarMenuEl.classList.add("hidden");
      topbarMenuEl.classList.remove("closing");
      topbarMenuEl.innerHTML = "";
      topbarMenuClosing = false;
    } else {
      topbarMenuClosing = true;
      topbarMenuEl.classList.add("closing");
      setTimeout(() => {
        topbarMenuEl.classList.add("hidden");
        topbarMenuEl.classList.remove("closing");
        topbarMenuEl.innerHTML = "";
        topbarMenuClosing = false;
      }, 180);
    }
    topbarTitle && topbarTitle.setAttribute("aria-expanded", "false");
    // Страховка от фантомного kb-active: на iOS открытие/закрытие плашки иногда
    // оставляло body.kb-active=true БЕЗ сфокусированного поля — композер висел
    // на translateY(-kb) с пустотой под ним (Кирилл: «после сворачивания списка
    // поднимается поле ввода»). Если клавиатуры реально нет (в фокусе ничего
    // текстового) — снимаем. Активное поле (печатает в composer) не трогаем.
    try {
      if (document.body.classList.contains("kb-active")) {
        const ae = document.activeElement;
        const editing = !!ae && (ae.tagName === "TEXTAREA" ||
          (ae.tagName === "INPUT" && !ae.readOnly) || ae.isContentEditable);
        if (!editing) setKb(0);
      }
    } catch (_) {}
  }

  function renderTopbarMenu() {
    if (!topbarMenuEl) return;
    topbarMenuEl.innerHTML = "";

    const tid = state.currentThread || "";
    const isFav = tid === "favorites";
    const items = [];

    // Полное название чата — первым пунктом. На узком экране сам input в топбаре
    // обрезается ellipsis'ом; здесь — без обрезки, чтобы можно было прочитать целиком.
    const fullTitle = (state.currentThreadTitle || "").trim();
    items.push({
      title: "Название чата",
      desc: fullTitle || "без названия",
      kind: "title",
      disabled: !fullTitle,
      action: () => { closeTopbarMenu(); },
    });

    items.push({
      title: "ID треда",
      desc: tid ? tid : "тред ещё не создан",
      disabled: !tid,
      action: () => { copyCurrentThreadId(); },
    });

    items.push({
      title: "Изменить название",
      desc: isFav ? "у избранного нельзя менять заголовок" : "вписать заголовок вручную",
      disabled: !tid || isFav,
      action: () => { openTopbarTitleEdit(); },
    });

    items.push({
      title: "Сгенерировать название",
      desc: topbarRegenerating
        ? "хайку придумывает заголовок…"
        : (isFav
            ? "у избранного нельзя менять заголовок"
            : "хайку придумает короткий заголовок по последним сообщениям"),
      busy: topbarRegenerating,
      disabled: !tid || isFav || topbarRegenerating,
      action: () => { triggerRegenerateTitle(); },
    });

    items.forEach((it, idx) => {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "topbar-menu-row";
      if (it.busy) row.classList.add("is-busy");
      if (it.disabled) row.setAttribute("disabled", "");
      if (it.kind) row.classList.add(`topbar-menu-row--${it.kind}`);
      row.setAttribute("role", "menuitem");
      row.setAttribute("data-idx", String(idx));

      const t = document.createElement("span");
      t.className = "topbar-menu-row-title";
      t.textContent = it.title;
      row.appendChild(t);

      const d = document.createElement("span");
      d.className = "topbar-menu-row-desc";
      d.textContent = it.desc;
      row.appendChild(d);

      let fired = false;
      const trigger = (ev) => {
        if (it.disabled) return;
        if (fired) return;
        fired = true;
        ev.stopPropagation();
        haptic.tap();
        try { it.action && it.action(); } catch (e) { console.error("topbar-menu action failed", e); }
      };
      row.addEventListener("pointerdown", (e) => { e.stopPropagation(); });
      row.addEventListener("pointerup",   (e) => { e.stopPropagation(); trigger(e); });
      row.addEventListener("click",       (e) => { e.stopPropagation(); trigger(e); });
      topbarMenuEl.appendChild(row);
    });
  }

  function openTopbarMenu() {
    if (!topbarMenuEl || !topbarTitle) return;
    if (document.body.classList.contains("editing-title")) return;
    renderTopbarMenu();
    topbarMenuEl.classList.remove("hidden");
    topbarMenuEl.classList.remove("closing");
    topbarMenuEl.setAttribute("aria-hidden", "false");
    topbarTitle.setAttribute("aria-expanded", "true");
  }

  function toggleTopbarMenu() {
    if (isTopbarMenuOpen() && !topbarMenuClosing) {
      closeTopbarMenu();
    } else {
      openTopbarMenu();
    }
  }

  function copyCurrentThreadId() {
    const tid = state.currentThread;
    if (!tid) { haptic.err(); return; }
    try {
      navigator.clipboard.writeText(String(tid));
      toast("ID треда скопирован");
      haptic.ok();
    } catch (_) { haptic.err(); }
    closeTopbarMenu();
  }

  function triggerRegenerateTitle() {
    const tid = state.currentThread;
    if (!tid || tid === "favorites") { haptic.err(); return; }
    if (topbarRegenerating) return;
    topbarRegenerating = true;
    haptic.bump();
    if (isTopbarMenuOpen()) renderTopbarMenu();
    try {
      sendCmd({ type: "thread_regenerate_title", thread_id: tid });
    } catch (e) {
      topbarRegenerating = false;
      if (isTopbarMenuOpen()) renderTopbarMenu();
      haptic.err();
    }
  }

  // Хук со стороны WS — серверный ответ thread_title_regen_done сбрасывает busy.
  window.__onThreadTitleRegenDone = function (ok, message) {
    topbarRegenerating = false;
    if (ok) {
      try { toast("заголовок обновлён"); } catch (_) {}
      haptic.ok();
    } else {
      try { toast(message || "не вышло обновить заголовок"); } catch (_) {}
      haptic.warn();
    }
    if (isTopbarMenuOpen()) renderTopbarMenu();
  };

  // Редактирование названия — тот же #topbar-title input, просто
  // переключается из readonly в writable (по аналогии с .routine-title-input).
  let _topbarEditCur = "";
  let _topbarEditOpen = false;

  function closeTopbarEdit(save) {
    if (!_topbarEditOpen || !topbarTitle) return;
    _topbarEditOpen = false;
    if (save) {
      const newTitle = (topbarTitle.value || "").trim().slice(0, 80);
      if (newTitle && newTitle !== _topbarEditCur && state.currentThread && state.currentThread !== "favorites") {
        try {
          sendCmd({ type: "thread_rename", thread_id: state.currentThread, title: newTitle });
          haptic.ok();
        } catch (_) { haptic.err(); }
        state.currentThreadTitle = newTitle;
        topbarTitle.value = newTitle;
      } else {
        topbarTitle.value = _topbarEditCur;
      }
    } else {
      topbarTitle.value = _topbarEditCur;
      haptic.tap();
    }
    topbarTitle.readOnly = true;
    topbarTitle.tabIndex = -1;
    try { topbarTitle.setAttribute("inputmode", "none"); } catch (_) {}
    try { topbarTitle.blur(); } catch (_) {}
    document.body.classList.remove("editing-title");
    autosizeTopbarTitle();
  }

  function openTopbarTitleEdit() {
    if (!topbarTitle) return;
    if (!state.currentThread) return;
    if (state.currentThread === "favorites") {
      try { toast("у избранного нельзя менять заголовок"); } catch (_) {}
      haptic.warn();
      return;
    }
    if (_topbarEditOpen) return;
    closeTopbarMenu(true);

    _topbarEditOpen = true;
    _topbarEditCur = (state.currentThreadTitle || topbarTitle.value || "").trim();

    document.body.classList.add("editing-title");
    topbarTitle.readOnly = false;
    topbarTitle.tabIndex = 0;
    try { topbarTitle.removeAttribute("inputmode"); } catch (_) {}

    requestAnimationFrame(() => {
      try { topbarTitle.focus({ preventScroll: true }); topbarTitle.select(); }
      catch (_) { try { topbarTitle.focus(); topbarTitle.select(); } catch (_) {} }
    });
  }

  if (topbarTitle) {
    topbarTitle.addEventListener("keydown", (e) => {
      if (!_topbarEditOpen) return;
      if (e.key === "Enter")       { e.preventDefault(); closeTopbarEdit(true); }
      else if (e.key === "Escape") { e.preventDefault(); closeTopbarEdit(false); }
    });
    topbarTitle.addEventListener("blur", () => {
      if (!_topbarEditOpen) return;
      closeTopbarEdit(true);
    });
    topbarTitle.addEventListener("input", () => { autosizeTopbarTitle(); });
    autosizeTopbarTitle();
  }

  (function bindTopbarTitle() {
    if (!topbarTitle) return;
    const LONG_PRESS_MS = 480;
    const MOVE_THRESHOLD = 10;

    const cancelLongPress = () => {
      if (topbarLongPressTimer) { clearTimeout(topbarLongPressTimer); topbarLongPressTimer = 0; }
    };

    topbarTitle.addEventListener("pointerdown", (e) => {
      if (e.button && e.button !== 0) return;
      if (_topbarEditOpen) return;
      // iOS WKWebView в readonly режиме всё равно ловит фокус и показывает
      // popover AutoFill/Copy/Paste — preventDefault его глушит.
      try { e.preventDefault(); } catch (_) {}
      topbarPointerDown = true;
      topbarLongPressFired = false;
      topbarPointerStart = { x: e.clientX, y: e.clientY };
      cancelLongPress();
      topbarLongPressTimer = setTimeout(() => {
        if (!topbarPointerDown) return;
        topbarLongPressFired = true;
        topbarTitle.classList.remove("holding");
        haptic.bump();
        openTopbarTitleEdit();
      }, LONG_PRESS_MS);
      topbarTitle.classList.add("holding");
    });

    topbarTitle.addEventListener("pointermove", (e) => {
      if (!topbarPointerDown || !topbarPointerStart) return;
      const dx = Math.abs(e.clientX - topbarPointerStart.x);
      const dy = Math.abs(e.clientY - topbarPointerStart.y);
      if (dx > MOVE_THRESHOLD || dy > MOVE_THRESHOLD) {
        cancelLongPress();
        topbarTitle.classList.remove("holding");
        topbarPointerDown = false;
      }
    });

    topbarTitle.addEventListener("pointerup", (e) => {
      if (!topbarPointerDown) return;
      topbarPointerDown = false;
      topbarTitle.classList.remove("holding");
      cancelLongPress();
      if (topbarLongPressFired) return; // уже открыли inline-edit
      // короткий тап
      haptic.tap();
      toggleTopbarMenu();
    });

    topbarTitle.addEventListener("pointercancel", () => {
      topbarPointerDown = false;
      cancelLongPress();
      topbarTitle.classList.remove("holding");
    });

    topbarTitle.addEventListener("click", (e) => {
      // pointerup уже сделал всю работу — глушим click чтобы не сработал второй раз
      // (и не зацепил debug-overlay 4-tap counter).
      e.preventDefault();
      e.stopPropagation();
      if (topbarLongPressFired) { topbarLongPressFired = false; }
    });

    topbarTitle.addEventListener("contextmenu", (e) => e.preventDefault());
  })();

  // Закрытие меню по тапу вне его.
  document.addEventListener("pointerdown", (e) => {
    if (!isTopbarMenuOpen()) return;
    if (topbarMenuEl.contains(e.target)) return;
    if (topbarTitle && topbarTitle.contains(e.target)) return;
    closeTopbarMenu();
  }, true);
  window.addEventListener("resize", () => closeTopbarMenu(true));

  // ===== debug overlay (4 тапа по топбару → BUSY-лог; showDebugDump доступна на window.__debugDump) =====
  (function setupDebugOverlay() {
    const topbarEl = document.getElementById("topbar");
    if (!topbarEl) return;
    let taps = [];
    const TAP_WINDOW_MS = 1200;
    topbarEl.addEventListener("click", (e) => {
      // не мешаем кнопкам внутри топбара (☰, conn-status, рутины)
      if (e.target.closest("button")) return;
      const now = Date.now();
      taps = taps.filter((t) => now - t < TAP_WINDOW_MS);
      taps.push(now);
      if (taps.length >= 4) {
        taps = [];
        try { openBusyLogOverlay(); } catch (_) {}
      }
    });

    function fmt(v) {
      if (v === null || v === undefined) return String(v);
      if (typeof v === "number") return Number.isFinite(v) ? v.toFixed(1) : String(v);
      return String(v);
    }

    function showDebugDump() {
      const cs = getComputedStyle(chatEl);
      const root = getComputedStyle(document.documentElement);
      const lines = [];
      lines.push("=== DEBUG DUMP ===");
      lines.push("time: " + new Date().toISOString());
      lines.push("ua: " + (navigator.userAgent || "").slice(0, 120));
      lines.push("");
      lines.push("--- viewport ---");
      lines.push("window.innerHeight: " + window.innerHeight);
      lines.push("window.visualViewport.height: " + (window.visualViewport ? fmt(window.visualViewport.height) : "n/a"));
      lines.push("window.visualViewport.offsetTop: " + (window.visualViewport ? fmt(window.visualViewport.offsetTop) : "n/a"));
      lines.push("--vh: " + root.getPropertyValue("--vh").trim());
      lines.push("--kb: " + root.getPropertyValue("--kb").trim());
      lines.push("--safe-top: " + root.getPropertyValue("--safe-top").trim());
      lines.push("--safe-bot: " + root.getPropertyValue("--safe-bot").trim());
      lines.push("");
      lines.push("--- state ---");
      lines.push("startMode: " + state.startMode);
      lines.push("currentThread: " + state.currentThread);
      lines.push("currentThreadTitle: " + state.currentThreadTitle);
      lines.push("userScrolledUp: " + state.userScrolledUp);
      lines.push("historyLoaded: " + state.historyLoaded + " / " + state.historyTotal);
      lines.push("pendingScrollRestore: " + JSON.stringify(state.pendingScrollRestore));
      lines.push("_kbActive: " + (state._kbActive ?? "n/a"));
      lines.push("body.className: " + document.body.className);
      lines.push("html.className: " + document.documentElement.className);
      lines.push("activeElement: " + (document.activeElement ? document.activeElement.tagName + "." + document.activeElement.className : "null"));
      lines.push("window.scrollY: " + window.scrollY + "  window.scrollX: " + window.scrollX);
      lines.push("");
      lines.push("--- #chat ---");
      const cr = chatEl.getBoundingClientRect();
      lines.push("rect.top: " + fmt(cr.top) + "  rect.bottom: " + fmt(cr.bottom));
      lines.push("rect.height: " + fmt(cr.height) + "  rect.width: " + fmt(cr.width));
      lines.push("scrollTop: " + chatEl.scrollTop + "  scrollHeight: " + chatEl.scrollHeight + "  clientHeight: " + chatEl.clientHeight);
      lines.push("display: " + cs.display + "  flex-direction: " + cs.flexDirection);
      lines.push("justify-content: " + cs.justifyContent + "  align-items: " + cs.alignItems);
      lines.push("padding: " + cs.paddingTop + " " + cs.paddingRight + " " + cs.paddingBottom + " " + cs.paddingLeft);
      lines.push("transform: " + cs.transform);
      lines.push("min-height: " + cs.minHeight + "  max-height: " + cs.maxHeight);
      lines.push("overflow-y: " + cs.overflowY);
      lines.push("");
      lines.push("--- children (" + chatEl.children.length + ") ---");
      const kids = Array.from(chatEl.children);
      kids.forEach((el, i) => {
        const r = el.getBoundingClientRect();
        const ecs = getComputedStyle(el);
        const cls = el.className || "(no class)";
        const txt = (el.textContent || "").replace(/\s+/g, " ").trim().slice(0, 80);
        const inlineStyle = (el.getAttribute && el.getAttribute("style")) || "";
        lines.push("[" + i + "] " + el.tagName.toLowerCase() + "." + cls);
        lines.push("    rect.top: " + fmt(r.top) + "  rect.left: " + fmt(r.left) + "  rect.width: " + fmt(r.width) + "  rect.height: " + fmt(r.height) + "  display: " + ecs.display);
        lines.push("    margin: " + ecs.marginTop + " " + ecs.marginBottom + "  align-self: " + ecs.alignSelf);
        lines.push("    color: " + ecs.color + "  bg: " + ecs.backgroundColor);
        lines.push("    opacity: " + ecs.opacity + "  visibility: " + ecs.visibility + "  z-index: " + ecs.zIndex);
        lines.push("    transform: " + ecs.transform + "  filter: " + ecs.filter + "  mix-blend: " + ecs.mixBlendMode);
        lines.push("    content-visibility: " + (ecs.contentVisibility || "n/a") + "  clip-path: " + ecs.clipPath);
        if (inlineStyle) lines.push("    inline-style: " + inlineStyle.slice(0, 200));
        if (txt) lines.push("    text: " + txt);
      });

      lines.push("");
      lines.push("--- body/app/topbar overlays ---");
      const bodyCs = getComputedStyle(document.body);
      const appEl = document.getElementById("app");
      const topbarEl = document.getElementById("topbar");
      lines.push("body bg: " + bodyCs.backgroundColor + "  color: " + bodyCs.color);
      if (appEl) {
        const acs = getComputedStyle(appEl);
        const ar = appEl.getBoundingClientRect();
        lines.push("#app rect.top: " + fmt(ar.top) + "  height: " + fmt(ar.height) + "  bg: " + acs.backgroundColor + "  transform: " + acs.transform + "  opacity: " + acs.opacity);
      }
      if (topbarEl) {
        const tcs = getComputedStyle(topbarEl);
        const tr = topbarEl.getBoundingClientRect();
        lines.push("#topbar rect.top: " + fmt(tr.top) + "  bottom: " + fmt(tr.bottom) + "  height: " + fmt(tr.height) + "  bg: " + tcs.backgroundColor + "  z-index: " + tcs.zIndex);
      }
      const beforeCs = getComputedStyle(document.body, "::before");
      const afterCs = getComputedStyle(document.body, "::after");
      lines.push("body::before content: " + beforeCs.content + "  height: " + beforeCs.height + "  bg: " + beforeCs.backgroundColor + "  z-index: " + beforeCs.zIndex);
      lines.push("body::after  content: " + afterCs.content + "  height: " + afterCs.height + "  bg: " + afterCs.backgroundColor + "  z-index: " + afterCs.zIndex);

      lines.push("");
      lines.push("--- elementsFromPoint(centerX, chatMid) ---");
      try {
        const cx = Math.round(cr.left + cr.width / 2);
        const cy = Math.round(cr.top + cr.height / 2);
        const stack = document.elementsFromPoint(cx, cy);
        lines.push("point: (" + cx + ", " + cy + ")  stack depth: " + stack.length);
        stack.slice(0, 8).forEach((el, i) => {
          const cls = el.className || "(no class)";
          lines.push("  [" + i + "] " + el.tagName.toLowerCase() + "." + cls);
        });
      } catch (e) {
        lines.push("elementsFromPoint failed: " + e.message);
      }

      const dump = lines.join("\n");

      // overlay
      let ov = document.getElementById("debug-overlay");
      if (ov) ov.remove();
      ov = document.createElement("div");
      ov.id = "debug-overlay";
      ov.className = "debug-overlay";
      const bar = document.createElement("div");
      bar.className = "debug-overlay-bar";
      function copyDumpToClipboard() {
        // iOS Telegram WebView часто не даёт navigator.clipboard.writeText —
        // делаем сразу execCommand через скрытую textarea (работает в user gesture).
        let ok = false;
        try {
          const ta = document.createElement("textarea");
          ta.value = dump;
          ta.setAttribute("readonly", "");
          ta.style.position = "fixed";
          ta.style.top = "0";
          ta.style.left = "0";
          ta.style.width = "1px";
          ta.style.height = "1px";
          ta.style.opacity = "0";
          ta.style.pointerEvents = "none";
          document.body.appendChild(ta);
          ta.focus();
          ta.select();
          ta.setSelectionRange(0, dump.length);
          ok = document.execCommand("copy");
          ta.remove();
        } catch (_) { ok = false; }
        if (!ok && navigator.clipboard && navigator.clipboard.writeText) {
          try {
            navigator.clipboard.writeText(dump);
            ok = true;
          } catch (_) {}
        }
        return ok;
      }
      const copyBtn = document.createElement("button");
      copyBtn.textContent = "Скопировать всё";
      copyBtn.className = "debug-overlay-btn";
      copyBtn.addEventListener("click", () => {
        const ok = copyDumpToClipboard();
        copyBtn.textContent = ok ? "Скопировано ✓" : "не вышло";
        setTimeout(() => { copyBtn.textContent = "Скопировать всё"; }, 1500);
      });
      const repaintBtn = document.createElement("button");
      repaintBtn.textContent = "Force repaint";
      repaintBtn.className = "debug-overlay-btn";
      repaintBtn.addEventListener("click", () => {
        ov.remove();
        forceRepaintChat();
      });
      const closeBtn = document.createElement("button");
      closeBtn.textContent = "Закрыть";
      closeBtn.className = "debug-overlay-btn";
      closeBtn.addEventListener("click", () => ov.remove());
      bar.appendChild(copyBtn);
      bar.appendChild(repaintBtn);
      bar.appendChild(closeBtn);
      const pre = document.createElement("pre");
      pre.className = "debug-overlay-pre";
      pre.textContent = dump;
      ov.appendChild(bar);
      ov.appendChild(pre);
      document.body.appendChild(ov);
    }
    window.__debugDump = showDebugDump;
  })();

  modalClose.addEventListener("click", () => { haptic.tap(); modal.classList.add("hidden"); });
  modal.addEventListener("click", (e) => {
    if (e.target !== modal) return;
    // v1027: пока катится откат версии — тап по дим-бэкдропу НЕ гасит попап.
    // Баг был такой: hold-fire срабатывает автоматически на 0.9с, палец ещё
    // прижат к строке версии; через 180мс vHoldFire дёргает renderVersionsModal,
    // тело перестраивается в короткий running-стейт («Накатываю vNNN…»), карточка
    // съёживается и уходит из-под пальца на бэкдроп; синтетический click от
    // отпускания попадал в сам modal (e.target===modal) и закрывал попап сразу
    // после старта. Крестик (modalClose) не трогаем — это сознательный выход и
    // страховка от залипания, если сервер не пришлёт done/error.
    if (state.versionsDeploy && state.versionsDeploy.status === "running") return;
    haptic.tap();
    modal.classList.add("hidden");
  });

  // drawer
  threadsBtn.addEventListener("click", () => {
    if (state.drawerOpen) closeDrawer(); else openDrawer();
  });
  drawerClose.addEventListener("click", () => { haptic.tap(); closeDrawer(); });
  // На iOS touchstart вне input блюрит фокус ДО click — поэтому ловим pointerdown
  // и фиксируем «был ли фокус внутри drawer» заранее, чтобы по клику только закрыть клаву.
  let drawerOverlaySwallowClick = false;
  const onOverlayDown = (e) => {
    const ae = document.activeElement;
    if (ae && drawer.contains(ae) && (ae.tagName === "INPUT" || ae.tagName === "TEXTAREA" || ae.isContentEditable)) {
      drawerOverlaySwallowClick = true;
      try { ae.blur(); } catch (_) {}
      try { haptic.tap(); } catch (_) {}
    }
  };
  drawerOverlay.addEventListener("pointerdown", onOverlayDown);
  drawerOverlay.addEventListener("touchstart", onOverlayDown, { passive: true });
  drawerOverlay.addEventListener("click", () => {
    if (drawerOverlaySwallowClick) {
      drawerOverlaySwallowClick = false;
      return;
    }
    haptic.tap();
    closeDrawer();
  });
  threadNewBtn.addEventListener("click", () => {
    haptic.bump();
    closeDrawer();
    // Свитч на стартовую страницу — стэшим приклеи текущего треда, достаём
    // приклеи startMode (если они были).
    {
      const _prevKey = _attachKeyFor(state.currentThread, !!state.startMode);
      const _newKey = _attachKeyFor(null, true);
      if (_prevKey !== _newKey) {
        _stashAttachmentsFor(_prevKey);
        _unstashAttachmentsFor(_newKey);
        try { renderAttachRow(); } catch (_) {}
      }
    }
    state.currentThread = null;
    resetChipsToDefaults();
    chatEl.innerHTML = "";
    renderStartPage();
    updateBusyUI();
    try { inputEl.focus({ preventScroll: true }); } catch { inputEl.focus(); }
  });
  if (threadToggleBtn) {
    threadToggleBtn.addEventListener("click", () => {
      haptic.bump();
      if (!state.drawerOpen) openDrawer();
      const next = state.drawerView === "home" ? "chats" : "home";
      setDrawerView(next, { smooth: true });
    });
  }

  if (drawerHeaderEl && drawerViews) {
    let hStartX = 0, hStartY = 0;
    let hLocked = "";
    let hDragging = false;
    let activeEl = null;
    let incomingEl = null;
    let viewW = 0;
    let didDrag = false;

    drawerHeaderEl.addEventListener("touchstart", (e) => {
      const t = e.touches[0];
      hStartX = t.clientX; hStartY = t.clientY;
      hLocked = ""; hDragging = true; didDrag = false;
      viewW = drawerViews.clientWidth || 1;
      const cur = state.drawerView;
      const other = cur === "home" ? "chats" : "home";
      activeEl = drawerViews.querySelector(`.drawer-view[data-view="${cur}"]`);
      incomingEl = drawerViews.querySelector(`.drawer-view[data-view="${other}"]`);
    }, { passive: true });

    drawerHeaderEl.addEventListener("touchmove", (e) => {
      if (!hDragging) return;
      const t = e.touches[0];
      const dx = t.clientX - hStartX;
      const dy = t.clientY - hStartY;
      if (!hLocked) {
        if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
        hLocked = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
        if (hLocked === "x") {
          drawerViews.classList.add("dragging");
          try { haptic.tap(); } catch (_) {}
        }
      }
      if (hLocked === "x") {
        didDrag = true;
        const adj = Math.max(0, Math.min(viewW, dx));
        if (activeEl) activeEl.style.transform = `translate3d(${adj}px, 0, 0)`;
        if (incomingEl) incomingEl.style.transform = `translate3d(${adj - viewW}px, 0, 0)`;
      }
    }, { passive: true });

    const clickKill = (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      ev.stopImmediatePropagation();
    };

    const endHeader = (e) => {
      if (!hDragging) return;
      hDragging = false;
      if (hLocked !== "x") return;
      drawerViews.classList.remove("dragging");
      const t = (e.changedTouches && e.changedTouches[0]) || null;
      const dx = t ? t.clientX - hStartX : 0;
      const threshold = Math.min(viewW * 0.25, 60);
      if (dx > threshold) {
        try { haptic.bump(); } catch (_) {}
        const next = state.drawerView === "home" ? "chats" : "home";
        setDrawerView(next, { smooth: true, fromDrag: true });
      } else {
        setDrawerView(state.drawerView, { smooth: true, fromDrag: true });
      }
      if (didDrag) {
        drawerHeaderEl.addEventListener("click", clickKill, { capture: true });
        setTimeout(() => {
          drawerHeaderEl.removeEventListener("click", clickKill, { capture: true });
        }, 400);
      }
    };
    drawerHeaderEl.addEventListener("touchend", endHeader, { passive: true });
    drawerHeaderEl.addEventListener("touchcancel", endHeader, { passive: true });
  }

  // ===== thread search wiring =====
  if (threadSearchInput) {
    threadSearchInput.addEventListener("input", () => {
      const val = threadSearchInput.value || "";
      if (val.trim() && state.drawerOpen && state.drawerView !== "chats") {
        setDrawerView("chats", { smooth: true });
      }
      // зеркалим в tech-поиск, чтобы на странице «Техническое» был тот же запрос.
      try {
        const ts = document.getElementById("tech-search-input");
        if (ts && ts.value !== val) {
          ts.value = val;
          const clr = document.getElementById("tech-search-clear");
          if (clr) clr.classList.toggle("hidden", !val);
          state.techQuery = val;
          if (typeof renderTechItems === "function") renderTechItems();
        }
      } catch (_) {}
      updateScopeChipsVisibility();
      updateSearchHistoryVisibility();
      if (state.search.debounceTimer) clearTimeout(state.search.debounceTimer);
      state.search.debounceTimer = setTimeout(() => {
        state.search.debounceTimer = null;
        if (state.search.scope !== "threads") {
          runScopeSearch();
        } else {
          runTextSearch(val.trim());
        }
      }, 250);
    });
    threadSearchInput.addEventListener("focus", () => {
      haptic.tap();
      updateScopeChipsVisibility();
      updateSearchHistoryVisibility();
    });
    threadSearchInput.addEventListener("blur", () => {
      setTimeout(updateScopeChipsVisibility, 180);
      setTimeout(() => {
        const q = (threadSearchInput.value || "").trim();
        if (q && q.length >= 2) addSearchHistory(q);
        hideSearchHistory();
      }, 180);
    });
    threadSearchInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (state.search.debounceTimer) {
          clearTimeout(state.search.debounceTimer);
          state.search.debounceTimer = null;
        }
        const q = (threadSearchInput.value || "").trim();
        if (q) addSearchHistory(q);
        hideSearchHistory();
        runAISearch();
      } else if (e.key === "Escape") {
        e.preventDefault();
        resetThreadSearch(true);
      }
    });
  }
  if (threadSearchClear) {
    threadSearchClear.addEventListener("click", () => {
      haptic.tap();
      resetThreadSearch(true);
      try { threadSearchInput && threadSearchInput.focus(); } catch (_) {}
    });
  }
  if (threadSearchAI) {
    threadSearchAI.addEventListener("click", () => runAISearch());
  }

  const scopeChips = document.getElementById("scope-chips");
  if (scopeChips) {
    setupScopeCarousel(scopeChips);
    scopeChips.addEventListener("click", (e) => {
      const btn = e.target.closest(".scope-chip");
      if (!btn) return;
      const next = btn.dataset.scope || "threads";
      if (next === state.search.scope) return;
      haptic.tap();
      setSearchScope(next);
    });
  }

  function setupScopeCarousel(box) {
    if (box.dataset.carousel === "1") return;
    const originals = Array.from(box.children);
    if (!originals.length) return;
    for (let i = 0; i < 2; i++) {
      originals.forEach((o) => box.appendChild(o.cloneNode(true)));
    }
    box.dataset.carousel = "1";
    let blockW = 0;
    function measureBlock() {
      const kids = box.children;
      if (kids.length < originals.length) return 0;
      const firstRect = kids[0].getBoundingClientRect();
      const lastRect = kids[originals.length - 1].getBoundingClientRect();
      const gap = parseFloat(getComputedStyle(box).columnGap || getComputedStyle(box).gap || "0") || 0;
      return (lastRect.right - firstRect.left) + gap;
    }
    function recenter() {
      blockW = measureBlock();
      if (blockW > 0) box.scrollLeft = blockW;
    }
    box.__recenter = recenter;
    box.addEventListener("scroll", () => {
      if (!blockW) blockW = measureBlock();
      if (!blockW) return;
      if (box.scrollLeft < blockW * 0.25) {
        box.scrollLeft += blockW;
      } else if (box.scrollLeft > blockW * 1.75) {
        box.scrollLeft -= blockW;
      }
    }, { passive: true });
  }

  // attachments + voice
  // Не звать registerPlugin как fallback — он создаёт прокси даже без нативки
  // и pickImages/pickFiles падают «not implemented on iOS». Опираемся только на
  // уже зарегистрированный плагин: есть нативный класс в IPA → есть Plugins.X.
  const getCameraPlugin = () => window.Capacitor?.Plugins?.Camera || null;
  const getFilePickerPlugin = () => window.Capacitor?.Plugins?.FilePicker || null;
  const hasCapacitorNative = () => !!(window.Capacitor && typeof window.Capacitor.isNativePlatform === "function" && window.Capacitor.isNativePlatform() && typeof window.Capacitor.registerPlugin === "function");
  (function showAppVersion() {
    // Источник правды — APP_BUILD (синхронно с CACHE_VERSION в sw.js).
    // Бампается одной правкой на каждый деплой; ручная "Версия 1.77" больше
    // не нужна — раздражало рассинхрон ручной надписи с реальной свежестью.
    const slot = document.querySelector("[data-app-version]");
    if (slot) slot.textContent = window.APP_BUILD || "?";
  })();
  // Спросить SW его внутренние счётчики через MessageChannel. Резолвится
  // с объектом {totalFetch, crossSeen, mediaSeen, mediaPutOk, mediaPutErr, version}
  // или null если SW недоступен / не ответил за 500мс.
  function askSwStats() {
    return new Promise((resolve) => {
      try {
        const ctrl = navigator.serviceWorker && navigator.serviceWorker.controller;
        if (!ctrl || typeof MessageChannel === "undefined") return resolve(null);
        const ch = new MessageChannel();
        let done = false;
        const t = setTimeout(() => { if (!done) { done = true; resolve(null); } }, 500);
        ch.port1.onmessage = (e) => {
          if (done) return;
          done = true;
          clearTimeout(t);
          resolve(e.data || null);
        };
        ctrl.postMessage({ type: "GET_STATS" }, [ch.port2]);
      } catch (_) { resolve(null); }
    });
  }

  function _fmtBytes(b) {
    if (b < 1024) return `${b} Б`;
    if (b < 1024 * 1024) return `${(b / 1024).toFixed(1)} КБ`;
    return `${(b / (1024 * 1024)).toFixed(1)} МБ`;
  }

  // Собирает срез текущего состояния кеша: IDB-треды/история, IDB-медиа,
  // SW-счётчики (если controller жив), таймстамп последнего save. Источник
  // для попапа «кеш» и для авто-обновления, если он открыт в момент save.
  async function gatherCacheStats() {
    const db = await idb();
    const threads = await new Promise((res) => {
      try {
        const tx = db.transaction("kv", "readonly");
        const r = tx.objectStore("kv").get("threads");
        r.onsuccess = () => res(Array.isArray(r.result) ? r.result.length : 0);
        r.onerror = () => res(0);
      } catch (_) { res(0); }
    });
    const histCount = await new Promise((res) => {
      try {
        const tx = db.transaction("history", "readonly");
        const r = tx.objectStore("history").count();
        r.onsuccess = () => res(r.result || 0);
        r.onerror = () => res(0);
      } catch (_) { res(0); }
    });
    const mStats = await mediaIdbStats(true);
    const meta = await idbGet("kv", "meta");
    const sw = await askSwStats();
    return {
      threads,
      histCount,
      mediaCount: mStats.count,
      mediaBytes: mStats.bytes,
      sizes: mStats.sizes || [],
      lastUrls: mStats.lastUrls || [],
      savedAt: meta && meta.savedAt ? new Date(meta.savedAt) : null,
      sw,
    };
  }

  // Попап «кеш» — открывается из меню настроек по строке «Кеш». Внутри:
  // дешборд (что лежит в IDB, какие SW-счётчики, когда последний save),
  // кнопка «сбросить» (тот же путь что раньше был под openConfirm).
  let _cacheDashOpen = false;
  async function openCacheDashboard() {
    haptic.select();
    _cacheDashOpen = true;
    modalTitle.textContent = "кеш";
    modalBody.innerHTML = "";

    const box = document.createElement("div");
    box.className = "cache-dash";
    box.innerHTML = `<div class="cache-dash-loading">собираю статистику…</div>`;
    modalBody.appendChild(box);

    const actions = document.createElement("div");
    actions.className = "confirm-actions";
    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button";
    cancelBtn.className = "confirm-btn";
    cancelBtn.textContent = "закрыть";
    cancelBtn.addEventListener("click", () => {
      haptic.tap();
      _cacheDashOpen = false;
      modal.classList.add("hidden");
    });
    const wipeBtn = document.createElement("button");
    wipeBtn.type = "button";
    wipeBtn.className = "confirm-btn danger";
    wipeBtn.textContent = "сбросить";
    wipeBtn.addEventListener("click", () => {
      haptic.warn();
      _cacheDashOpen = false;
      modal.classList.add("hidden");
      openConfirm({
        title: "сбросить кэш?",
        message: "Удалю закэшированные ассеты, картинки и файлы из чатов, регистрацию сервис-воркера и локальное состояние (история вкладок, счётчики, реакции). Авторизация, тема, масштаб, автокоррект, хаптики и копи-код сохранятся.",
        okText: "сбросить",
        cancelText: "отмена",
        danger: true,
        onOk: async () => {
          await clearAppCache();
          try { logReload("cache_reset"); } catch (_) {}
          try {
            const u = new URL(location.href);
            u.searchParams.set("_v", Date.now().toString());
            location.replace(u.toString());
          } catch (_) { location.reload(); }
        },
      });
    });
    actions.appendChild(cancelBtn);
    actions.appendChild(wipeBtn);
    modalBody.appendChild(actions);

    modal.classList.remove("hidden");

    try {
      const s = await gatherCacheStats();
      if (!_cacheDashOpen) return;
      renderCacheDashboard(box, s);
    } catch (e) {
      box.textContent = `IDB ошибка: ${e && e.message || e}`;
    }

    // Если попап ещё открыт, а где-то параллельно прошёл save (см. cacheTouch
    // в saveSnapshot) — обновим цифры. Дёшево: одна доп. выборка.
    try {
      const refresh = async () => {
        if (!_cacheDashOpen) return;
        try {
          const s2 = await gatherCacheStats();
          if (_cacheDashOpen) renderCacheDashboard(box, s2);
        } catch (_) {}
      };
      window.addEventListener("maccode:cache-touched", refresh);
      const wasClose = cancelBtn.onclick;
      cancelBtn.addEventListener("click", () => {
        window.removeEventListener("maccode:cache-touched", refresh);
      }, { once: true });
    } catch (_) {}
  }

  function renderCacheDashboard(box, s) {
    box.innerHTML = "";
    const grid = document.createElement("div");
    grid.className = "cache-dash-grid";

    const rows = [];
    rows.push(["треды", `${s.threads}`]);
    rows.push(["истории", `${s.histCount}`]);

    if (s.mediaCount === 0) {
      rows.push(["медиа", "0"]);
    } else {
      const avg = s.mediaBytes / s.mediaCount;
      const minSz = s.sizes.length ? Math.min.apply(null, s.sizes) : 0;
      const maxSz = s.sizes.length ? Math.max.apply(null, s.sizes) : 0;
      rows.push(["медиа", `${s.mediaCount} · ${_fmtBytes(s.mediaBytes)}`]);
      rows.push(["размер", `${_fmtBytes(minSz)} … ${_fmtBytes(avg)} … ${_fmtBytes(maxSz)}`]);
    }

    if (s.sw) {
      let line = `f${s.sw.totalFetch || 0} · x${s.sw.crossSeen || 0} · m${s.sw.mediaSeen || 0} · ok${s.sw.mediaPutOk || 0}`;
      if ((s.sw.mediaPutErr || 0) > 0) line += ` · err${s.sw.mediaPutErr}`;
      rows.push(["SW", line]);
    } else {
      rows.push(["SW", "нет (WKWebView)"]);
    }

    if (s.savedAt) {
      const d = s.savedAt;
      const when = `${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")} · ${String(d.getDate()).padStart(2,"0")}.${String(d.getMonth()+1).padStart(2,"0")}`;
      rows.push(["сохранение", when]);
    } else {
      rows.push(["сохранение", "—"]);
    }

    for (const [k, v] of rows) {
      const dt = document.createElement("div");
      dt.className = "cache-dash-key";
      dt.textContent = k;
      const dd = document.createElement("div");
      dd.className = "cache-dash-val";
      dd.textContent = v;
      grid.appendChild(dt);
      grid.appendChild(dd);
    }
    box.appendChild(grid);

    if (s.lastUrls && s.lastUrls.length) {
      const ttl = document.createElement("div");
      ttl.className = "cache-dash-section";
      ttl.textContent = "последние URL";
      box.appendChild(ttl);
      const ul = document.createElement("ul");
      ul.className = "cache-dash-urls";
      for (const u of s.lastUrls.slice(0, 6)) {
        const li = document.createElement("li");
        li.textContent = u;
        ul.appendChild(li);
      }
      box.appendChild(ul);
    }
  }

  // Старый refreshCacheStats() рендерил подпись под версией. Слот удалён —
  // оставляем функцию как маркер «состояние кеша изменилось», чтобы открытый
  // попап мог сам подтянуть актуальные цифры (см. event maccode:cache-touched).
  function refreshCacheStats() {
    try { window.dispatchEvent(new CustomEvent("maccode:cache-touched")); } catch (_) {}
  }
  (function showIOSVersion() {
    if (!hasCapacitorNative()) return;
    const wrap = document.querySelector(".settings-version-ios");
    if (!wrap) return;
    const m = (navigator.userAgent || "").match(/MaccodNative\/([\d.]+)/);
    if (m) {
      const slot = wrap.querySelector("[data-ios-version]");
      if (slot) slot.textContent = m[1];
    }
    wrap.hidden = false;
  })();
  function htmlPickPhotos() {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "image/*,video/*";
    input.multiple = true;
    input.style.position = "fixed";
    input.style.left = "-9999px";
    document.body.appendChild(input);
    input.onchange = () => {
      const files = Array.from(input.files || []);
      if (files.length) handleFiles(files);
      setTimeout(() => input.remove(), 0);
    };
    input.click();
  }
  async function blobFromImageUrl(url, format) {
    try {
      const r = await fetch(url);
      if (r.ok) return await r.blob();
    } catch (_) {}
    return await new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        try {
          const c = document.createElement("canvas");
          c.width = img.naturalWidth;
          c.height = img.naturalHeight;
          c.getContext("2d").drawImage(img, 0, 0);
          const mime = (format || "jpeg").toLowerCase() === "png" ? "image/png" : "image/jpeg";
          c.toBlob((b) => resolve(b), mime, 0.92);
        } catch (_) { resolve(null); }
      };
      img.onerror = () => resolve(null);
      img.src = url;
    });
  }
  async function nativePickPhotos() {
    const Camera = getCameraPlugin();
    if (!Camera) { htmlPickPhotos(); return; }
    let res;
    try {
      res = await Camera.pickImages({ quality: 90, limit: 10 });
    } catch (e) {
      const msg = String((e && (e.message || e.code)) || "");
      if (/cancel/i.test(msg)) return;
      toast(`фото: ${msg || "ошибка"}`);
      return;
    }
    const photos = res?.photos || [];
    if (!photos.length) return;
    const files = [];
    for (const p of photos) {
      const url = p.webPath || p.path;
      if (!url) continue;
      const blob = await blobFromImageUrl(url, p.format);
      if (!blob) continue;
      const ext = (p.format || "jpeg").toLowerCase();
      const name = `IMG_${Date.now()}_${files.length + 1}.${ext}`;
      files.push(new File([blob], name, { type: blob.type || `image/${ext}` }));
    }
    if (files.length) handleFiles(files);
    else toast("фото не прочиталось");
  }
  async function nativeTakePhoto() {
    try {
      const Camera = getCameraPlugin();
      if (!Camera) throw new Error("no Camera plugin");
      const photo = await Camera.getPhoto({
        source: "CAMERA",
        resultType: "base64",
        quality: 90,
        saveToGallery: false,
      });
      if (photo?.base64String) {
        const ext = (photo.format || "jpeg").toLowerCase();
        window._filePickerReceive(`IMG_${Date.now()}.${ext}`, photo.base64String);
      }
    } catch (e) {
      const msg = (e && (e.message || e.code)) || "no plugin";
      if (!/cancel/i.test(String(msg))) toast(`камера: ${msg}`);
    }
  }
  async function nativePickFiles() {
    try {
      const FilePicker = getFilePickerPlugin();
      if (!FilePicker) throw new Error("no FilePicker plugin");
      const res = await FilePicker.pickFiles({ readData: true });
      const items = res?.files || [];
      const files = items.map((f) => {
        const raw = atob(f.data || "");
        const ab = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; i++) ab[i] = raw.charCodeAt(i);
        return new File([ab], f.name, { type: f.mimeType || guessMime(f.name) });
      });
      if (files.length) handleFiles(files);
    } catch (e) {
      const msg = (e && (e.message || e.code)) || "no plugin";
      if (!/cancel/i.test(String(msg))) toast(`файлы: ${msg}`);
    }
  }
  function openAttachSheet() {
    modalTitle.textContent = "прикрепить";
    modalBody.innerHTML = "";
    const ICO_PHOTO  = '<svg class="menu-ico" viewBox="0 0 16 16" width="16" height="16" shape-rendering="crispEdges" aria-hidden="true"><path fill="currentColor" d="M2 3h12v1h-12zM2 4h1v8h-1zM13 4h1v8h-1zM2 12h12v1h-12zM4 5h2v2h-2zM7 8h2v1h-2zM6 9h4v1h-4zM5 10h6v1h-6zM4 11h8v1h-8z"/></svg>';
    const ICO_CAMERA = '<svg class="menu-ico" viewBox="0 0 16 16" width="16" height="16" shape-rendering="crispEdges" aria-hidden="true"><path fill="currentColor" d="M5 3h4v1h-4zM3 4h10v1h-10zM3 5h1v7h-1zM12 5h1v7h-1zM3 12h10v1h-10zM7 6h2v1h-2zM6 7h1v2h-1zM9 7h1v2h-1zM7 9h2v1h-2zM10 5h2v1h-2z"/></svg>';
    const ICO_FOLDER = '<svg class="menu-ico" viewBox="0 0 16 16" width="16" height="16" shape-rendering="crispEdges" aria-hidden="true"><path fill="currentColor" d="M2 3h4v1h-4zM2 4h12v1h-12zM2 5h1v7h-1zM13 5h1v7h-1zM2 12h12v1h-12z"/></svg>';
    const ICO_CROSS  = '<svg class="menu-ico" viewBox="0 0 16 16" width="16" height="16" shape-rendering="crispEdges" aria-hidden="true"><path fill="currentColor" d="M3 3h2v1h-2zM11 3h2v1h-2zM4 4h2v1h-2zM10 4h2v1h-2zM5 5h2v1h-2zM9 5h2v1h-2zM6 6h2v1h-2zM8 6h2v1h-2zM7 7h2v1h-2zM7 8h2v1h-2zM6 9h2v1h-2zM8 9h2v1h-2zM5 10h2v1h-2zM9 10h2v1h-2zM4 11h2v1h-2zM10 11h2v1h-2zM3 12h2v1h-2zM11 12h2v1h-2z"/></svg>';
    // Если в IPA есть CAPCameraPlugin/FilePickerPlugin — открываем галерею
    // напрямую через Camera.pickImages / FilePicker.pickFiles. Если нет —
    // обе функции внутри упадут в htmlPickPhotos через getCameraPlugin()=null.
    const picks = [
      { label: "Фото и видео",      forId: "file-input-photos", ico: ICO_PHOTO,  pick: "photos", action: nativePickPhotos },
      { label: "Сделать фото",      forId: "file-input-camera", ico: ICO_CAMERA, pick: "camera", action: null },
      { label: "Файл с устройства", forId: "file-input-files",  ico: ICO_FOLDER, pick: "folder", action: nativePickFiles },
    ];
    picks.forEach(({ label, forId, ico, pick, action }) => {
      const el = action
        ? document.createElement("button")
        : document.createElement("label");
      el.className = "modal-pick";
      el.setAttribute("data-pick", pick);
      if (!action) el.htmlFor = forId;
      el.innerHTML = ico + label;
      el.addEventListener("click", () => {
        haptic.tap();
        setTimeout(() => modal.classList.add("hidden"), 0);
        if (action) setTimeout(action, 50);
      });
      modalBody.appendChild(el);
    });
    const cancel = document.createElement("button");
    cancel.className = "modal-pick";
    cancel.setAttribute("data-pick", "cancel");
    cancel.innerHTML = ICO_CROSS + "Отмена";
    cancel.onclick = () => {
      haptic.tap();
      modal.classList.add("hidden");
    };
    modalBody.appendChild(cancel);
    modal.classList.remove("hidden");
  }
  const useCustomAttachSheet = () => hasCapacitorNative();
  attachBtn.addEventListener("click", () => {
    haptic.tap();
    if (useCustomAttachSheet()) {
      openAttachSheet();
    } else {
      try { fileInput.click(); } catch (_) {}
    }
  });
  attachBtn.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (useCustomAttachSheet()) {
        openAttachSheet();
      } else {
        try { fileInput.click(); } catch (_) {}
      }
    }
  });

  function guessMime(name) {
    const ext = (name.split(".").pop() || "").toLowerCase();
    const map = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", gif: "image/gif",
      webp: "image/webp", heic: "image/heic", pdf: "application/pdf",
      mp4: "video/mp4", mov: "video/quicktime", mp3: "audio/mpeg", m4a: "audio/mp4",
      txt: "text/plain", md: "text/markdown", csv: "text/csv", json: "application/json",
      zip: "application/zip", docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation" };
    return map[ext] || "application/octet-stream";
  }

  window._filePickerReceive = function(name, b64) {
    try {
      const raw = atob(b64);
      const ab = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i++) ab[i] = raw.charCodeAt(i);
      const mime = guessMime(name);
      const file = new File([ab], name, { type: mime });
      handleFiles([file]);
    } catch (e) {
      toast("не прочитал файл");
    }
  };
  [fileInput, fileInputPhotos, fileInputCamera, fileInputFiles].forEach((inp) => {
    inp.addEventListener("change", () => {
      const files = Array.from(inp.files || []);
      handleFiles(files);
      inp.value = "";
    });
  });

  // ===== drag-and-drop file attach =====
  const dropOverlay = $("drop-overlay");
  let dragDepth = 0;
  document.addEventListener("dragenter", (e) => {
    if (!e.dataTransfer?.types?.includes("Files")) return;
    e.preventDefault();
    dragDepth++;
    dropOverlay?.classList.remove("hidden");
  });
  document.addEventListener("dragleave", (e) => {
    if (!e.dataTransfer?.types?.includes("Files")) return;
    dragDepth--;
    if (dragDepth <= 0) { dragDepth = 0; dropOverlay?.classList.add("hidden"); }
  });
  document.addEventListener("dragover", (e) => {
    if (!e.dataTransfer?.types?.includes("Files")) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "copy";
  });
  document.addEventListener("drop", (e) => {
    e.preventDefault();
    dragDepth = 0;
    dropOverlay?.classList.add("hidden");
    const files = Array.from(e.dataTransfer?.files || []);
    if (files.length) handleFiles(files);
  });

  bindLongPress(micBtn, 550, {
    isActive: () => state.recording,
    onActivate: startRec,
    onShortTapWhenActive: cancelRec,
  });

  const inputWrap = inputEl.parentElement;
  const syncInputContent = () => {
    if (inputWrap) inputWrap.classList.toggle("has-content", inputEl.value.length > 0);
  };
  // chip-bg НЕ дёргаем на каждый keystroke: набор текста не двигает сообщения
  // в чате, а getBoundingClientRect по всем .msg.user на длинном треде = сотни
